def tur_spread(kind):
    """Streuung (Grad, Halbwinkel) eines Geschützes; das Wagen-Geschütz ist genauer."""
    return 0.5 if kind == "flak" else TUR_SPREAD * (0.45 if kind == "car" else 0.7)


