class UiSlider:
    """Waagerechter Schieberegler: Beschriftung links, Wert rechts, darunter Schiene mit Knopf.
    Gezogen wird mit der linken Maustaste (Game.ui_slider_press / slider_follow)."""
    def __init__(self, parent, spec, x0, x1, z, binned=True):
        # binned=False (Hauptmenü): Zeichenreihenfolge = Reihenfolge im Szenengraph, sonst läge der Hintergrund darüber
        self.sp, self.x0, self.x1, self.z, self.on = spec, x0, x1, z, False
        self.zt = z - 0.065
        self.root = parent.attachNewNode("uislider")

        def lay(n, sort):
            n.setTransparency(TransparencyAttrib.MAlpha)
            if binned:
                n.setBin("fixed", sort)
            n.setDepthTest(False)
            n.setDepthWrite(False)
            return n

        def card(a, b, c, d, sort):
            cm = CardMaker("uis")
            cm.setFrame(a, b, c, d)
            return lay(self.root.attachNewNode(cm.generate()), sort)

        zt = self.zt
        self.lab = OnscreenText(text=spec.label, pos=(x0, z), scale=0.05, parent=self.root,
                                fg=(0.86, 0.92, 1.0, 1) if spec.enabled else (0.5, 0.52, 0.55, 1),
                                shadow=(0, 0, 0, 0.9), align=TextNode.ALeft, mayChange=False)
        self.val = OnscreenText(text="", pos=(x1, z), scale=0.05, parent=self.root, fg=(1.0, 0.85, 0.2, 1),
                                shadow=(0, 0, 0, 0.9), align=TextNode.ARight, mayChange=True)
        if binned:
            self.lab.setBin("fixed", 95)
            self.val.setBin("fixed", 95)
        self.track = card(x0, x1, zt - 0.007, zt + 0.007, 92)
        self.track.setColor(0.16, 0.22, 0.30, 1)
        self.fill = card(0.0, 1.0, zt - 0.007, zt + 0.007, 93)
        self.fill.setPos(x0, 0, 0)
        self.knob = card(-0.022, 0.022, -0.022, 0.022, 94)
        self.knob.setR(45.0)
        self.refresh()

    def value(self):
        return self.sp.get()

    def refresh(self):
        sp = self.sp
        v = max(sp.lo, min(sp.hi, self.value()))
        x = self.x0 + (v - sp.lo) / float(sp.hi - sp.lo) * (self.x1 - self.x0)
        self.fill.setSx(max(0.001, x - self.x0))
        self.knob.setPos(x, 0, self.zt)
        self.val.setText(sp.fmt(v))
        if sp.enabled:
            self.fill.setColor(1.0, 0.62, 0.14, 1)
            self.knob.setColor(*((1.0, 1.0, 0.78, 1) if self.on else (1.0, 0.85, 0.4, 1)))
        else:
            self.fill.setColor(0.35, 0.37, 0.40, 1)
            self.knob.setColor(0.5, 0.52, 0.55, 1)

    def hit(self, ax, az):
        return self.sp.enabled and self.x0 - 0.05 <= ax <= self.x1 + 0.05 and self.zt - 0.055 <= az <= self.z + 0.06

    def set_hot(self, on):
        if on != self.on:
            self.on = on
            self.refresh()

    def follow(self, mx):
        sp = self.sp
        t = max(0.0, min(1.0, (mx - self.x0) / (self.x1 - self.x0)))
        v = round((sp.lo + t * (sp.hi - sp.lo)) / sp.step) * sp.step
        v = int(v) if isinstance(sp.step, int) else round(v, 4)
        if v != sp.get():
            sp.set_(v)
        self.refresh()

    def destroy(self):
        self.lab.destroy()
        self.val.destroy()
        self.root.removeNode()


def over_or_driving(game):
    pl = game.player
    return pl.vehicle >= 0 or pl.heli >= 0 or pl.mount >= 0


class Crosshair:
    """Fadenkreuz aus vier Strichen mit Lücke in der Mitte. Die Striche rücken beim Gehen, Rennen, Drehen,
    in der Luft und nach Schüssen auseinander (ungenauer) und ziehen sich geduckt zusammen."""
    BASE, LEN, TH = 0.014, 0.024, 0.0026

    def __init__(self, parent):
        self.root = parent.attachNewNode("crosshair")
        self.gap = self.BASE
        self.arms = []
        for dx, dz in ((-1, 0), (1, 0), (0, 1), (0, -1)):
            hold = self.root.attachNewNode("arm")
            for grow, col in ((0.0012, (0, 0, 0, 0.7)), (0.0, (1, 1, 1, 0.92))):
                if dx:
                    fr = (0.0 - grow, self.LEN + grow, -self.TH - grow, self.TH + grow)
                else:
                    fr = (-self.TH - grow, self.TH + grow, 0.0 - grow, self.LEN + grow)
                cm = CardMaker("ch")
                cm.setFrame(*fr)
                c = hold.attachNewNode(cm.generate())
                c.setColor(*col)
                c.setTransparency(TransparencyAttrib.MAlpha)
            hold.setH(0)
            self.arms.append((hold, dx, dz))
        self.root.setBin("fixed", 38)
        self.root.setDepthTest(False)
        self.root.setDepthWrite(False)
        self.place(self.gap)

    def place(self, g):
        self.gap = g
        for hold, dx, dz in self.arms:
            # links/unten: Strich beginnt bei -(Lücke+Länge), rechts/oben bei +Lücke
            ox = g if dx > 0 else (-g - self.LEN if dx < 0 else 0.0)
            oz = g if dz > 0 else (-g - self.LEN if dz < 0 else 0.0)
            hold.setPos(ox, 0, oz)

    def target(self, walk, run, turn, air, bloom, crouch, hip=0.0):
        return max(0.008, min(0.14, self.BASE + hip + 0.010 * walk + 0.018 * run + 0.026 * turn
                              + 0.022 * air + 0.012 * bloom - 0.004 * crouch))

    def update(self, dt, **k):
        t = self.target(**k)
        a = min(1.0, (22.0 if t > self.gap else 11.0) * dt)         # schnell auf, langsamer zu
        self.place(self.gap + (t - self.gap) * a)

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()


def project_dir(cam, pt, tv):
    """Weltpunkt pt auf den Bildschirm (aspect2d-Einheiten) projizieren. cam = (x, y, z, Kurs, Nick, Roll) der
    Kamera, tv = tan(halber vertikaler Öffnungswinkel). -> (x, z) oder None, wenn der Punkt hinter der Kamera liegt."""
    cx, cy, cz, h, p, r = cam
    h, p, r = math.radians(h), math.radians(p), math.radians(r)
    f = (-math.sin(h) * math.cos(p), math.cos(h) * math.cos(p), math.sin(p))
    r0 = (math.cos(h), math.sin(h), 0.0)
    u0 = cross(r0, f)
    cr, sr = math.cos(r), math.sin(r)
    right = tuple(a * cr - b * sr for a, b in zip(r0, u0))
    up = tuple(b * cr + a * sr for a, b in zip(r0, u0))
    v = (pt[0] - cx, pt[1] - cy, pt[2] - cz)
    yc = v[0] * f[0] + v[1] * f[1] + v[2] * f[2]
    if yc < 0.5:
        return None
    return ((v[0] * right[0] + v[1] * right[1] + v[2] * right[2]) / yc / tv,
            (v[0] * up[0] + v[1] * up[1] + v[2] * up[2]) / yc / tv)


class HeliSight:
    """Fadenkreuz des Helikopters: Ring mit Punkt, wird auf den Punkt vor der Nase gesetzt."""
    R = 0.05

    def __init__(self, parent):
        self.root = parent.attachNewNode("heli_sight")
        back = self.root.attachNewNode("hs_back")
        self.fg = self.root.attachNewNode("hs_fg")
        n = 20
        bars = []
        for i in range(n):                                    # Ring aus kurzen Strichen
            a = 360.0 * i / n
            bars.append((a, self.R, 0.022, 0.0035))
        for a in (0, 90, 180, 270):                           # vier Striche nach aussen
            bars.append((a, self.R + 0.02, 0.026, 0.0028))
        for par, grow, col in ((back, 0.0016, (0, 0, 0, 0.7)), (self.fg, 0.0, (0.6, 1.0, 0.6, 0.95))):
            for a, rad, ln, th in bars:
                h = par.attachNewNode("s")
                h.setR(a)
                cm = CardMaker("hs")
                cm.setFrame(rad - ln / 2 - grow, rad + ln / 2 + grow, -th - grow, th + grow)
                c = h.attachNewNode(cm.generate())
                c.setColor(*col)
                c.setTransparency(TransparencyAttrib.MAlpha)
            cm = CardMaker("hs_dot")
            cm.setFrame(-0.004 - grow, 0.004 + grow, -0.004 - grow, 0.004 + grow)
            c = par.attachNewNode(cm.generate())
            c.setColor(*col)
            c.setTransparency(TransparencyAttrib.MAlpha)
        self.root.setBin("fixed", 37)
        self.root.setDepthTest(False)
        self.root.setDepthWrite(False)

    def place(self, x, z):
        self.root.setPos(x, 0, z)

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()


class HitMark:
    """Treffermarker wie in Shootern: vier kurze Schrägstriche um das Fadenkreuz (mit dunklem Rand)."""

    def __init__(self, parent):
        self.root = parent.attachNewNode("hitmarker")
        back = self.root.attachNewNode("hm_back")
        self.fg = self.root.attachNewNode("hm_fg")
        for ang in (45, 135, 225, 315):
            for par, fr, col in ((back, (0.016, 0.066, -0.0055, 0.0055), (0, 0, 0, 0.75)),
                                 (self.fg, (0.02, 0.06, -0.0025, 0.0025), (1, 1, 1, 1))):
                h = par.attachNewNode("t")
                h.setR(ang)
                cm = CardMaker("hm")
                cm.setFrame(*fr)
                c = h.attachNewNode(cm.generate())
                c.setColor(*col)
                c.setTransparency(TransparencyAttrib.MAlpha)
        self.root.setBin("fixed", 40)
        self.root.setDepthTest(False)
        self.root.setDepthWrite(False)

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()

    def setFg(self, col):
        self.fg.setColorScale(*col)

    def pop(self, k):                  # kurzes Aufploppen beim Treffer
        self.root.setScale(1.0 + 0.5 * max(0.0, min(1.0, k)))


def gadget_parts(kind):
    """Quader eines Gadgets (Mitte am Boden, Oberseite +z, Vorderseite +y): (cx,cy,cz,sx,sy,sz,Farbe)."""
    if kind == GAD_C4:
        return [(0, 0, 0.02, 0.16, 0.10, 0.04, (0.80, 0.76, 0.62)),
                (0, 0, 0.0415, 0.17, 0.03, 0.007, (0.12, 0.12, 0.12)),
                (0.045, 0, 0.0545, 0.045, 0.03, 0.026, (0.10, 0.10, 0.12)),
                (0.045, 0, 0.07, 0.012, 0.012, 0.006, (1.0, 0.12, 0.05)),
                (-0.05, 0, 0.052, 0.012, 0.09, 0.03, (0.10, 0.10, 0.10))]
    if kind == GAD_CLAY:
        return [(0, 0, 0.045, 0.22, 0.035, 0.09, (0.20, 0.28, 0.18)),
                (-0.1, 0.012, 0.045, 0.04, 0.04, 0.09, (0.20, 0.28, 0.18)),
                (0.1, 0.012, 0.045, 0.04, 0.04, 0.09, (0.20, 0.28, 0.18)),
                (0, 0.02, 0.05, 0.16, 0.004, 0.04, (0.60, 0.62, 0.42)),
                (0, 0, 0.095, 0.05, 0.02, 0.012, (0.10, 0.10, 0.10)),
                (-0.08, -0.025, 0.012, 0.012, 0.012, 0.03, (0.15, 0.15, 0.15)),
                (0.08, -0.025, 0.012, 0.012, 0.012, 0.03, (0.15, 0.15, 0.15))]
    return [(0, 0, 0.06, 0.07, 0.07, 0.12, (0.12, 0.13, 0.15)),
            (0, 0, 0.035, 0.076, 0.076, 0.016, (0.90, 0.75, 0.10)),
            (0.02, 0, 0.19, 0.006, 0.006, 0.15, (0.72, 0.72, 0.75)),
            (0, 0, 0.127, 0.03, 0.03, 0.012, (0.30, 0.80, 1.0))]


def gadget_mesh(kind):
    m = Mesh()
    rng = random.Random(30 + kind)
    for cx, cy, cz, sx, sy, sz, col in gadget_parts(kind):
        box(m, cx, cy, cz, sx, sy, sz, col, rng)
    return m


def parts_icon(rects, width, height, name):
    """Flaches Symbol aus Rechtecken (a0,a1,b0,b1,Farbe) in der x/z-Ebene, Mitte im Ursprung: dunkler Rand, dann Farbe."""
    a0_, a1_ = min(r[0] for r in rects), max(r[1] for r in rects)
    b0_, b1_ = min(r[2] for r in rects), max(r[3] for r in rects)
    pad = 0.02
    k = min(width / (a1_ - a0_ + 2 * pad), height / (b1_ - b0_ + 2 * pad))
    ma, mb = (a0_ + a1_) / 2, (b0_ + b1_) / 2
    m = Mesh(lit=False)

    def quad(a0, a1, b0, b1, col):
        p = [((a - ma) * k, 0.0, (b - mb) * k) for a, b in ((a0, b0), (a1, b0), (a1, b1), (a0, b1))]
        m.tri(p[0], p[1], p[2], col)
        m.tri(p[0], p[2], p[3], col)

    o = 0.008
    for a0, a1, b0, b1, _c in rects:
        quad(a0 - o, a1 + o, b0 - o, b1 + o, (0.02, 0.02, 0.03))
    for a0, a1, b0, b1, c in rects:
        quad(a0, a1, b0, b1, tuple(min(1.0, v * 1.5 + 0.28) for v in c))
    np = NodePath(m.node(name))
    np.setTwoSided(True)
    return np


def att_icon(wi, si, v, width=0.26, height=0.08):
    """Symbol eines Ausrüstungsteils (Seitenansicht) für Waffe wi; None bei der Serienausstattung."""
    w = WEAPONS[wi]
    prts = list(att_parts(w.name, si, v))
    if not prts:
        return None
    mp = MAG_PARTS.get(w.name)
    if si == 1 and mp is not None:
        prts = [(cx, cy + mp[1], cz + mp[2], sx, sy, sz, c) for cx, cy, cz, sx, sy, sz, c in prts]
        polys = []                                   # das Magazin selbst dazu, der Aufsatz darüber
        for sh_ in GUN_SHAPES[w.name]["mag"]:
            polys += shape_polys(sh_, (mp[0], mp[1], mp[2]))
        return polys_icon(polys + rect_polys(prts), width, height, "atticon%d_%d_%d" % (wi, si, v), pad=0.02, edge=0.0035)
    return polys_icon(rect_polys(prts), width, height, "atticon%d_%d_%d" % (wi, si, v), pad=0.02, edge=0.0035)


def scope_icon(sc, width=0.3, height=0.14):
    """Seitenansicht eines Visiers als Symbol."""
    if sc == SC_IRON:       # Kimme hinten, Korn vorn
        rects = [(-0.16, 0.16, -0.012, 0.0, (0.3, 0.3, 0.33)),
                 (-0.14, -0.1, 0.0, 0.07, _DK), (-0.1, -0.08, 0.04, 0.07, _DK),
                 (0.09, 0.14, 0.0, 0.03, _DK2), (0.105, 0.125, 0.03, 0.075, (0.5, 0.5, 0.5)),
                 (-0.125, -0.115, 0.07, 0.074, _DOT), (0.108, 0.122, 0.074, 0.08, (0.95, 0.5, 0.1))]
    else:
        rects = [(cy - sy / 2, cy + sy / 2, cz - sz / 2, cz + sz / 2, col)
                 for _cx, cy, cz, _sx, sy, sz, col in scope_parts(sc, "", rel=True)]
    return parts_icon(rects, width, height, "scopeicon%d" % sc)


# ------------------------------------------------------------------ Stat-System und Hover-Hinweise
TIP_GREEN, TIP_RED, TIP_BLUE = (0.45, 0.95, 0.5, 1), (1.0, 0.5, 0.45, 1), (0.55, 0.8, 1.0, 1)
MOD_LABELS = {"dmg": ("Schaden", True), "speed": ("Mündungsgeschw.", True), "spread": ("Streuung Hüfte", False),
              "ads_spread": ("Streuung Zielen", False), "kick": ("Rückstoss", False),
              "kick_yaw": ("Seitl. Rückstoss", False), "bloom": ("Streuungszuwachs", False),
              "reload": ("Nachladezeit", False), "mag": ("Magazingrösse", True), "reserve": ("Reservemunition", True)}


def _c01(v):
    return max(0.0, min(1.0, v))


def weapon_stats(w):
    """Kennwerte einer Waffe als (Name, Anzeige, Balken 0..1); ein längerer Balken ist immer besser."""
    tot = w.dmg * w.pellets
    dps = tot / max(w.interval, 0.01)
    ads = w.spread * w.ads_spread
    dmg_txt = f"{tot:g}" if w.pellets == 1 else f"{tot:g} ({w.pellets} x {w.dmg:g})"
    return [("Schaden", dmg_txt, _c01(tot / 90.0)),
            ("Schaden / Sekunde", f"{dps:.0f}", _c01(dps / 200.0)),
            ("Feuerrate", f"{60.0 / w.interval:.0f}/min", _c01(60.0 / w.interval / 900.0)),
            ("Mündungsgeschw.", f"{w.speed:.0f} m/s", _c01(w.speed / 700.0)),
            ("Genauigkeit Hüfte", f"{w.spread:.1f}°", _c01(1.0 - w.spread / 5.0)),
            ("Genauigkeit Zielen", f"{ads:.2f}°", _c01(1.0 - ads / 2.0)),
            ("Rückstoss", f"{w.kick:.1f}°", _c01(1.0 - w.kick / 6.0)),
            ("Nachladen", f"{w.reload:.1f} s", _c01(1.0 - (w.reload - 1.0) / 3.5)),
            ("Magazin / Reserve", f"{w.mag} / {w.max_reserve}", _c01(w.mag / 32.0))]


def mod_lines(mods):
    """Wirkung eines Aufsatzes als Textzeilen [(Text, Farbe)]."""
    out = []
    for k, f in mods.items():
        lab, up_good = MOD_LABELS[k]
        pct = int(round((f - 1.0) * 100))
        out.append((f"{lab}  {pct:+d}%", TIP_GREEN if (f > 1.0) == up_good else TIP_RED))
    return out or [("keine Änderung", (0.7, 0.75, 0.8, 1))]


class Tooltip:
    """Hinweisfeld neben der Maus. Inhalt wird mit title()/sub()/bar()/para() beschrieben und beim Wechsel neu gebaut."""
    W = 0.88

    def __init__(self, parent):
        self.parent, self.key, self.root, self.size = parent, None, None, (self.W, 0.3)
        self.items, self.texts = [], []

    # ---- Inhalt
    def title(self, s, col=(1.0, 0.85, 0.3, 1)):
        self.items.append(("title", s, col, 0.075))

    def sub(self, s, col=(0.62, 0.7, 0.8, 1)):
        self.items.append(("sub", s, col, 0.05))

    def gap(self, h=0.02):
        self.items.append(("gap", "", None, h))

    def bar(self, label, val, norm, col=TIP_BLUE, base_norm=None):
        if base_norm is not None and abs(norm - base_norm) > 0.004:
            col = TIP_GREEN if norm > base_norm else TIP_RED
        self.items.append(("bar", (label, val, norm), col, 0.056))

    def para(self, s, col=(0.88, 0.92, 0.96, 1), width=50):
        import textwrap
        for ln in textwrap.wrap(s, width) or [""]:
            self.items.append(("para", ln, col, 0.043))

    # ---- Darstellung
    def clear(self):
        for t in self.texts:
            try:
                t.destroy()
            except Exception:
                pass
        self.texts = []
        if self.root is not None:
            self.root.removeNode()
            self.root = None
        self.items, self.key = [], None

    hide = clear

    def _card(self, x, z, w, h, col):
        cm = CardMaker("tc")
        cm.setFrame(0, w, -h, 0)
        n = self.root.attachNewNode(cm.generate())
        n.setPos(x, 0, z)
        n.setColor(*col)
        n.setTransparency(TransparencyAttrib.MAlpha)
        n.setDepthTest(False)
        n.setDepthWrite(False)
        return n

    def _text(self, s, x, z, scale, col, align=TextNode.ALeft):
        t = OnscreenText(text=s, parent=self.root, pos=(x, z), scale=scale, fg=col, shadow=(0, 0, 0, 0.9),
                         align=align, mayChange=False)
        self.texts.append(t)

    def _draw(self):
        W = self.W
        H = 0.05 + sum(it[3] for it in self.items)
        self.root = self.parent.attachNewNode("tooltip")
        self._card(-0.006, 0.006, W + 0.012, H + 0.012, (0.75, 0.8, 0.88, 1.0))
        self._card(0, 0, W, H, (0.05, 0.06, 0.09, 1.0))
        y = -0.025
        for kind, a, col, h in self.items:
            if kind == "title":
                self._text(a, 0.03, y - 0.05, 0.05, col)
            elif kind == "sub":
                self._text(a, 0.03, y - 0.032, 0.03, col)
            elif kind == "para":
                self._text(a, 0.03, y - 0.031, 0.031, col)
            elif kind == "bar":
                label, val, norm = a
                self._text(label, 0.03, y - 0.038, 0.031, (0.78, 0.84, 0.9, 1))
                self._card(0.40, y - 0.018, 0.30, 0.022, (0.16, 0.18, 0.23, 1.0))
                self._card(0.40, y - 0.018, max(0.004, 0.30 * norm), 0.022, col)
                self._text(val, W - 0.03, y - 0.038, 0.031, col, TextNode.ARight)
            y -= h
        self.size = (W, H)

    def show(self, key, build, m, aspect=1.6):
        if key != self.key or self.root is None:
            self.clear()
            self.key = key
            build(self)
            self._draw()
        w, h = self.size
        x, z = m[0] + 0.07, m[1] - 0.04
        if x + w > aspect - 0.03:
            x = m[0] - 0.07 - w
        x = max(-aspect + 0.03, x)
        z = max(-0.97 + h, min(0.97, z))
        self.root.setPos(x, -0.4, z)             # y < 0: wird nach allem anderen gezeichnet


def tip_weapon(wi, att=None, role=""):
    """Baut das Stat-Feld einer Waffe (mit Aufsätzen, falls gesetzt)."""
    att = att_valid(att)
    if att == ATT_NONE:
        att = None

    def build(t):
        base, w = WEAPONS[wi], eff_weapon(wi, att)
        t.title(w.name)
        names = [f"{ATT_SLOTS[i]}: {ATTACHMENTS[i][v][0]}" for i, v in enumerate(att or ()) if v]
        t.sub(role + ("" if names else ("   -   " if role else "") + "Serienausstattung"))
        for nm in names:
            t.sub(nm, (1.0, 0.85, 0.3, 1))
        t.gap(0.012)
        bn = {r[0]: r[2] for r in weapon_stats(base)}
        for lab, val, norm in weapon_stats(w):
            t.bar(lab, val, norm, TIP_BLUE, bn[lab] if att else None)
        t.gap(0.012)
        extra = f"Kopfschuss x{w.head_mult:g}" + ("   |   Dauerfeuer" if w.auto else "   |   Einzelfeuer")
        if w.pellets > 1:
            extra += f"   |   {w.pellets} Schrotkugeln"
        t.sub(extra)
    return build


def tip_gadget(gi):
    def build(t):
        t.title(GADGETS[gi])
        t.sub("Gadget")
        t.gap(0.012)
        t.para(GAD_INFO[gi])
    return build


def tip_attachment(si, v):
    def build(t):
        name, info, mods = ATTACHMENTS[si][v]
        t.title(name)
        t.sub(f"Ausrüstungsteil: {ATT_SLOTS[si]}")
        t.gap(0.012)
        t.para(info)
        t.gap(0.012)
        for txt, col in mod_lines(mods):
            t.items.append(("para", txt, col, 0.043))
    return build


def weapon_anchors(wi, width=0.42, height=0.2):
    """Ankerpunkte (x, z) im Symbol einer Waffe (wie weapon_icon): Visier, Lauf (Mündung), Magazin."""
    w = WEAPONS[wi]
    muzzle = GUN_PARTS[w.name][1]
    y0, y1, z0, z1 = weapon_frame(w.name)
    pad = 0.03
    k = min(width / (y1 - y0 + 2 * pad), height / (z1 - z0 + 2 * pad))
    my, mz = (y0 + y1) / 2, (z0 + z1) / 2
    f = lambda y, z: ((y - my) * k, (z - mz) * k)               # noqa: E731
    sy_, sz_ = SCOPE_MOUNT.get(w.name, (0.1, 0.04))
    mp = MAG_PARTS.get(w.name)
    return {"scope": f(sy_, max(sz_, z1 - 0.02) if w.name not in SCOPE_MOUNT else sz_),
            "barrel": f(muzzle[1], muzzle[2]),
            "mag": f(mp[1], mp[2]) if mp is not None else f(0.1, -0.02),
            "grip": f((muzzle[1] + (mp[1] if mp is not None else 0.1)) / 2 + 0.02, z0 + 0.012)}


class LoadoutScreen:
    """Loadout konfigurieren: die gewählte Primär- und Sekundärwaffe als Symbol, von ihnen führen Linien zu Slots
    (Visier, Lauf, Magazin). Ein Klick auf den Visier-Slot der Primärwaffe öffnet die Auswahl der Visiere."""

    def __init__(self, game, on_close):
        self.g, self.on_close = game, on_close
        self.root = game.aspect2d.attachNewNode("loadscreen")
        self.rects = []                    # (x0, x1, z0, z1, Aktion, Rahmenknoten, Normalfarbe)
        self.texts = []
        self.open_slot = None              # None | "scope" | ("att", Primärwaffe?, Platz)
        self.hover_idx = -1
        self.tips = []                     # (x0, x1, z0, z1, (Schlüssel, Baufunktion)) - reine Hover-Flächen
        self.preview = None                # (Hauptwaffe?, Platz, Aufsatz) unter der Maus: wird in den Balken vorgezeigt
        self.tip = Tooltip(game.aspect2d)
        self.build()

    @staticmethod
    def sb(np, n):
        """Wie die Setup-Seite: keine "fixed"-Ebenen, alles in einer Ebene in Erstellungsreihenfolge."""
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setDepthTest(False)
        np.setDepthWrite(False)

    def card(self, x, z, w, h, col, sort):
        cm = CardMaker("lc")
        cm.setFrame(-w / 2, w / 2, -h / 2, h / 2)
        n = self.root.attachNewNode(cm.generate())
        n.setPos(x, 0, z)
        n.setColor(*col)
        n.setTransparency(TransparencyAttrib.MAlpha)
        self.sb(n, sort)
        return n

    def text(self, s, x, z, scale, col, align=TextNode.ACenter):
        t = OnscreenText(text=s, parent=self.root, pos=(x, z), scale=scale, fg=col, shadow=(0, 0, 0, 0.8),
                         align=align, mayChange=False)
        self.texts.append(t)
        return t

    def line(self, p0, p1, col=(0.75, 0.82, 0.92, 0.9)):
        ls = LineSegs()
        ls.setThickness(2.0)
        ls.setColor(*col)
        ls.moveTo(p0[0], 0, p0[1])
        ls.drawTo(p1[0], 0, p1[1])
        n = self.root.attachNewNode(ls.create())
        self.sb(n, 22)
        return n

    def destroy(self):
        for t in self.texts:
            t.destroy()
        self.texts = []
        self.tip.clear()
        self.root.removeNode()

    def rebuild(self):
        for t in self.texts:
            t.destroy()
        self.texts = []
        self.root.removeNode()
        self.root = self.g.aspect2d.attachNewNode("loadscreen")
        self.rects = []
        self.tips = []
        self.hover_idx = -1
        self.tip.clear()
        self.build()

    def slot(self, x, z, label, content_icon, content_text, action, note="", tip=None, active=False):
        """Ein Zubehör-Slot (Karte). content_icon: Symbol oder None. -> Mittelpunkt der linken Kante."""
        w, h = 0.66, 0.115
        enabled = action is not None
        base = (1.0, 0.85, 0.2, 1.0) if active else (0.45, 0.45, 0.5, 0.75) if enabled else (0.25, 0.25, 0.3, 0.6)
        frame = self.card(x, z, w, h, base, 19)
        self.card(x, z, w - 0.024, h - 0.024, (0.07, 0.08, 0.11, 0.95), 20)
        self.text(label, x - w / 2 + 0.03, z + 0.018, 0.026, (0.7, 0.78, 0.86, 1) if enabled else (0.5, 0.52, 0.56, 1),
                  TextNode.ALeft)
        if content_icon is not None:
            content_icon.reparentTo(self.root)
            content_icon.setPos(x - w / 2 + 0.16, 0, z - 0.008)
            content_icon.setScale(0.8)
            self.sb(content_icon, 21)
        self.text(content_text, x - w / 2 + (0.34 if content_icon is not None else 0.03), z - 0.034, 0.036,
                  (1, 1, 1, 1) if enabled else (0.55, 0.57, 0.6, 1), TextNode.ALeft)
        if note:
            self.text(note, x + w / 2 - 0.03, z - 0.034, 0.024, (0.5, 0.52, 0.56, 1), TextNode.ARight)
        self.rects.append((x - w / 2, x + w / 2, z - h / 2, z + h / 2, action, frame, base, tip))
        return (x - w / 2, z)

    def hatch(self, xa, xb, zc, h, col):
        """Schraffierter Balkenabschnitt (Zugewinn grün, Verlust rot)."""
        if xb - xa < 0.003:
            return
        self.card((xa + xb) / 2, zc, xb - xa, h, (col[0], col[1], col[2], 0.28), 23)
        ls = LineSegs()
        ls.setThickness(1.5)
        ls.setColor(col[0], col[1], col[2], 1.0)
        x = xa - h
        while x < xb:
            t0 = max(0.0, (xa - x) / h)
            t1 = min(1.0, (xb - x) / h)
            if t1 > t0:
                ls.moveTo(x + t0 * h, 0, zc - h / 2 + t0 * h)
                ls.drawTo(x + t1 * h, 0, zc - h / 2 + t1 * h)
            x += 0.011
        n = self.root.attachNewNode(ls.create())
        self.sb(n, 24)

    def stat_panel(self, x0, cz, wi, att):
        """Werte der Waffe links neben dem Symbol; Aufsätze erscheinen als schraffierter Zugewinn/Verlust."""
        base = weapon_stats(WEAPONS[wi])
        cur = weapon_stats(eff_weapon(wi, att))
        W = 0.75
        rh = min(0.082, 0.50 / len(cur))               # bei vielen Zeilen enger, damit beide Waffenfelder passen
        H = 0.085 + rh * len(cur)
        top = cz + H / 2
        self.card(x0 + W / 2, cz, W + 0.01, H + 0.01, (0.55, 0.6, 0.68, 1.0), 16)
        self.card(x0 + W / 2, cz, W, H, (0.05, 0.06, 0.09, 1.0), 17)
        self.text("WERTE", x0 + 0.02, top - 0.058, 0.034, (1.0, 0.85, 0.3, 1), TextNode.ALeft)
        self.text("grün = besser, rot = schlechter als Serie" if att and tuple(att) != ATT_NONE else "Serienausstattung",
                  x0 + W - 0.02, top - 0.058, 0.021, (0.62, 0.7, 0.8, 1), TextNode.ARight)
        bx0, bw, bh = x0 + 0.27, 0.19, 0.022
        for r, ((lab, _bv, nb), (_l, val, ne)) in enumerate(zip(base, cur)):
            z = top - 0.085 - rh * (r + 0.5) - 0.0
            self.text(lab, x0 + 0.015, z - 0.01, 0.026, (0.78, 0.84, 0.9, 1), TextNode.ALeft)
            self.card(bx0 + bw / 2, z, bw, bh, (0.16, 0.18, 0.23, 1.0), 20)
            solid = min(nb, ne)
            if solid > 0.003:
                self.card(bx0 + solid * bw / 2, z, solid * bw, bh, (0.45, 0.7, 1.0, 1.0), 21)
            if ne > nb + 0.004:
                self.hatch(bx0 + nb * bw, bx0 + ne * bw, z, bh, TIP_GREEN)
            elif ne < nb - 0.004:
                self.hatch(bx0 + ne * bw, bx0 + nb * bw, z, bh, TIP_RED)
            col = TIP_GREEN if ne > nb + 0.004 else TIP_RED if ne < nb - 0.004 else (1, 1, 1, 1)
            self.text(val, x0 + W - 0.015, z - 0.01, 0.026, col, TextNode.ARight)

    def weapon_block(self, wi, cx, cz, caption, primary):
        w = WEAPONS[wi]
        self.text(caption, cx, cz + 0.2, 0.045, (1.0, 0.85, 0.3, 1))
        sc_ = self.g.loadout[3] if (primary and w.name in SCOPE_MOUNT) else None
        ic = weapon_icon(wi, extra=loadout_extra(wi, sc_, self.g.loadout[4 if primary else 5]), scope=sc_)
        ic.reparentTo(self.root)
        ic.setPos(cx, 0, cz)
        ic.setScale(1.5)
        self.sb(ic, 21)
        anc = weapon_anchors(wi)
        g = self.g
        idx = 4 if primary else 5
        att = g.loadout[idx]
        shown = list(att)
        if self.preview is not None and self.preview[0] == primary:           # Aufsatz unter der Maus vorzeigen
            shown[self.preview[1]] = self.preview[2]
        self.stat_panel(-1.32, cz, wi, tuple(shown))
        sx, step = 0.62, 0.125                   # Slotspalte rechts: Visier (nur Hauptwaffe), Lauf, Magazin, Griff
        n = 4 if (primary and w.name in SCOPE_MOUNT) else 3
        rows = [cz + (n - 1) / 2 * step - i * step for i in range(n)]
        ends = {}
        if n == 4:
            sc = g.loadout[3]
            ends["scope"] = self.slot(sx, rows.pop(0), "VISIER", scope_icon(sc), SCOPES[sc], lambda: self.toggle_scope(),
                                      "", active=self.open_slot == "scope")
        for si, key in enumerate(("barrel", "mag", "grip")):
            v = att[si]
            act = ("att", primary, si)
            ends[key] = self.slot(sx, rows.pop(0), ATT_SLOTS[si].upper(), att_icon(wi, si, v), ATTACHMENTS[si][v][0],
                                  (lambda pr=primary, si=si: self.toggle_att(pr, si)), "",
                                  tip=(("a", si, v), tip_attachment(si, v)), active=self.open_slot == act)
        for key, end_pt in ends.items():
            ax, az = anc[key]
            a = (cx + ax * 1.5, cz + az * 1.5)
            self.line(a, end_pt)
            self.card(a[0], a[1], 0.018, 0.018, (1.0, 0.85, 0.3, 1), 23)

    def build(self):
        g = self.g
        self.card(0, 0, 6.0, 2.0, (0.02, 0.03, 0.05, 0.95), 15)
        self.text("Loadout konfigurieren", 0, 0.88, 0.075, (1.0, 0.78, 0.3, 1))
        self.weapon_block(g.loadout[0], -0.2, 0.5, f"Hauptwaffe:  {WEAPONS[g.loadout[0]].name}", True)
        self.weapon_block(g.loadout[1], -0.2, -0.12, f"Kleinwaffe:  {WEAPONS[g.loadout[1]].name}", False)
        if self.open_slot == "scope":            # Auswahl der Visiere
            self.text("Visier wählen", 0, -0.43, 0.045, (0.85, 0.9, 0.95, 1))
            for i, s in enumerate(range(4)):
                x = (i - 1.5) * 0.5
                sel = g.loadout[3] == s
                base = (1.0, 0.85, 0.2, 1.0) if sel else (0.4, 0.4, 0.45, 0.8)
                frame = self.card(x, -0.65, 0.46, 0.3, base, 19)
                self.card(x, -0.65, 0.436, 0.276, (0.07, 0.08, 0.11, 0.96), 20)
                ic = scope_icon(s)
                ic.reparentTo(self.root)
                ic.setPos(x, 0, -0.6)
                self.sb(ic, 21)
                self.text(SCOPES[s], x, -0.72, 0.038, (1, 0.9, 0.3, 1) if sel else (1, 1, 1, 1))
                self.text(SCOPE_INFO[s], x, -0.775, 0.024, (0.65, 0.72, 0.8, 1))
                self.rects.append((x - 0.23, x + 0.23, -0.8, -0.5, (lambda s=s: self.pick_scope(s)), frame, base))
        elif isinstance(self.open_slot, tuple):    # Auswahl eines Ausrüstungsteils
            _k, prim, si = self.open_slot
            cur = g.loadout[4 if prim else 5][si]
            wi_ = g.loadout[0 if prim else 1]
            self.text(f"{ATT_SLOTS[si]} wählen - Mauszeiger darüber zeigt die Wirkung", 0, -0.45, 0.04, (0.85, 0.9, 0.95, 1))
            n = len(ATTACHMENTS[si])
            for v in range(n):
                x = (v - (n - 1) / 2) * 0.5
                sel = cur == v
                base = (1.0, 0.85, 0.2, 1.0) if sel else (0.4, 0.4, 0.45, 0.8)
                frame = self.card(x, -0.68, 0.46, 0.32, base, 19)
                self.card(x, -0.68, 0.436, 0.296, (0.07, 0.08, 0.11, 0.96), 20)
                name, info, mods = ATTACHMENTS[si][v]
                self.text(name, x, -0.575, 0.04, (1, 0.9, 0.3, 1) if sel else (1, 1, 1, 1))
                ic = att_icon(wi_, si, v, 0.26, 0.07)
                if ic is not None:
                    ic.reparentTo(self.root)
                    ic.setPos(x, 0, -0.63)
                    self.sb(ic, 21)
                for j, (txt, col) in enumerate(mod_lines(mods)[:4]):
                    self.text(txt, x, -0.70 - 0.036 * j, 0.025, col)
                self.rects.append((x - 0.23, x + 0.23, -0.84, -0.52,
                                   (lambda pr=prim, si=si, v=v: self.pick_att(pr, si, v)), frame, base,
                                   (("a", si, v), tip_attachment(si, v))))
        else:
            self.text("Slot wählen, um Zubehör zu ändern - Mauszeiger über Waffe oder Slot zeigt die Werte",
                      0, -0.55, 0.036, (0.7, 0.78, 0.86, 1))
        base = (0.1, 0.17, 0.26, 0.95)
        frame = self.card(0, -0.93, 0.7, 0.1, base, 19)
        self.text("Fertig   (Esc)", 0, -0.945, 0.05, (1, 1, 1, 1))
        self.rects.append((-0.35, 0.35, -0.98, -0.88, self.on_close, frame, base))

    def toggle_scope(self):
        self.open_slot = None if self.open_slot == "scope" else "scope"
        self.rebuild()

    def pick_scope(self, s):
        self.g.set_scope(s)
        self.rebuild()

    def toggle_att(self, prim, si):
        key = ("att", prim, si)
        self.open_slot = None if self.open_slot == key else key
        self.rebuild()

    def pick_att(self, prim, si, v):
        self.g.set_att(prim, si, v)
        self.open_slot = None
        self.rebuild()

    def hit(self, m):
        if m is None:
            return -1
        for i, r in enumerate(self.rects):
            if r[0] <= m[0] <= r[1] and r[2] <= m[1] <= r[3] and r[4] is not None:
                return i
        return -1

    def hover(self, m):
        pv = None
        if m is not None and isinstance(self.open_slot, tuple):
            for r in self.rects:
                if (r[2] < -0.5 and len(r) > 7 and r[7] and r[7][0][0] == "a"
                        and r[0] <= m[0] <= r[1] and r[2] <= m[1] <= r[3]):
                    pv = (self.open_slot[1], r[7][0][1], r[7][0][2])
                    break
        if pv != self.preview:
            self.preview = pv
            self.rebuild()
        i = self.hit(m)
        if i != self.hover_idx:
            for j, r in enumerate(self.rects):
                r[5].setColor(*((0.45, 0.75, 1.0, 1.0) if j == i else r[6]))
            self.hover_idx = i
        tip = None
        if m is not None:
            for r in self.rects:
                if len(r) > 7 and r[7] and r[0] <= m[0] <= r[1] and r[2] <= m[1] <= r[3]:
                    tip = r[7]
                    break
            else:
                for x0, x1, z0, z1, t in self.tips:
                    if x0 <= m[0] <= x1 and z0 <= m[1] <= z1:
                        tip = t
                        break
        if tip is None:
            self.tip.clear()
        else:
            try:
                asp = float(self.g.getAspectRatio())
            except Exception:
                asp = 1.6
            self.tip.show(tip[0], tip[1], m, asp)

    def click(self, m):
        i = self.hit(m)
        if i >= 0:
            self.rects[i][4]()


class Picker:
    """Waffenwahl mit Bildern: zwei Reihen (Haupt- und Kleinwaffe) mit je drei Karten.
    Die Zifferntaste steht auf der Karte, die gewählte Waffe hat einen gelben Rahmen."""

    COL_X = (-0.40, 0.18, 0.76)                     # Mitten der drei Spalten
    LABEL_X = -1.02                                 # Zeilenbeschriftung links

    def __init__(self, parent, icons, z_main, z_side, z_gad=None, flat=False):
        """Tabelle: je Zeile eine Kategorie (Hauptwaffe, Kleinwaffe, Gadget) mit Beschriftung links und drei Karten."""
        self.flat = flat                 # flat: Reihenfolge nur nach Szenengraph (wie die Setup-Seite), ohne "fixed"-Bins
        self.root = parent.attachNewNode("picker")
        self.cards = []                  # (Slot 0/1/2, Waffe bzw. Gadget, Rahmen, Beschriftung)
        self.rects = []                  # (Slot, Waffe, x, z, halbe Höhe) für die Maus
        self.texts = []
        ch = min(0.29, abs(z_main - z_side) - 0.06)          # Kartenhöhe der Waffenzeilen
        gh = ch * 0.8                                          # Gadgetzeile etwas flacher
        rows = [(0, PRIMARIES, 1, z_main, "Hauptwaffe", ch), (1, SECONDARIES, 4, z_side, "Kleinwaffe", ch)]
        if z_gad is not None:
            rows.append((2, (GAD_C4, GAD_CLAY, GAD_BEACON), 7, z_gad, "Gadget", gh))
        top = z_main + ch / 2 + 0.05
        bot = rows[-1][3] - rows[-1][5] / 2 - 0.05
        cx, w = (self.LABEL_X - 0.05 + self.COL_X[2] + 0.27 + 0.05) / 2, self.COL_X[2] + 0.27 + 0.05 - self.LABEL_X + 0.05
        self.card(cx, (top + bot) / 2, w + 0.012, top - bot + 0.012, (0.55, 0.6, 0.68, 1.0), 16)
        self.card(cx, (top + bot) / 2, w, top - bot, (0.07, 0.08, 0.10, 1.0), 17)
        for r in range(len(rows) - 1):                      # Trennlinien zwischen den Zeilen
            zl = (rows[r][3] - rows[r][5] / 2 + rows[r + 1][3] + rows[r + 1][5] / 2) / 2
            self.card(cx, zl, w - 0.06, 0.003, (0.40, 0.45, 0.52, 1.0), 18)
        for slot, ids, first, z, title, h in rows:
            t = OnscreenText(text=title, parent=self.root, pos=(self.LABEL_X, z + 0.01), scale=0.052,
                             fg=(1.0, 0.82, 0.35, 1), shadow=(0, 0, 0, 0.8), align=TextNode.ALeft, mayChange=False)
            self.tbin(t)
            t2 = OnscreenText(text=f"Taste {first}-{first + 2}", parent=self.root, pos=(self.LABEL_X, z - 0.05),
                              scale=0.034, fg=(0.6, 0.66, 0.74, 1), shadow=(0, 0, 0, 0.8), align=TextNode.ALeft,
                              mayChange=False)
            self.tbin(t2)
            self.texts += [t, t2]
            for i, wi in enumerate(ids):
                x = self.COL_X[i]
                frame = self.card(x, z, 0.54, h, (0.38, 0.41, 0.46, 1.0), 19)
                self.card(x, z, 0.516, h - 0.024, (0.13, 0.15, 0.19, 1.0), 20)
                if slot < 2:
                    ic = icons[wi].copyTo(self.root)
                    ic.setPos(x, 0, z + 0.02 * h / 0.29)
                    ic.setScale(h / 0.29)
                    name = WEAPONS[wi].name
                else:
                    ic = gadget_icon(wi)
                    ic.reparentTo(self.root)
                    ic.setPos(x, 0, z + 0.035)
                    ic.setScale(0.55)
                    name = GADGETS[wi]
                self.sb(ic, 21)
                lbl = OnscreenText(text=f"{first + i}   {name}", parent=self.root,
                                   pos=(x, z - h / 2 + 0.03), scale=0.042, fg=(1, 1, 1, 1),
                                   shadow=(0, 0, 0, 0.8), mayChange=True)
                self.tbin(lbl)
                self.texts.append(lbl)
                self.cards.append((slot, wi, frame, lbl))
                self.rects.append((slot, wi, x, z, h / 2 + 0.005))

    def sb(self, np, n):
        if self.flat:
            np.setTransparency(TransparencyAttrib.MAlpha)         # alles in derselben Ebene, Reihenfolge = Erstellungsreihenfolge
            np.setDepthTest(False)
            np.setDepthWrite(False)
        else:
            self.set_bin(np, n)

    def tbin(self, t):
        if not self.flat:
            t.setBin("fixed", 25)

    @staticmethod
    def set_bin(np, n):
        np.setBin("fixed", n)
        np.setDepthTest(False)
        np.setDepthWrite(False)

    def card(self, x, z, w, h, col, sort):
        cm = CardMaker("card")
        cm.setFrame(-w / 2, w / 2, -h / 2, h / 2)
        n = self.root.attachNewNode(cm.generate())
        n.setPos(x, 0, z)
        n.setColor(*col)
        n.setTransparency(TransparencyAttrib.MAlpha)
        self.sb(n, sort)
        return n

    def hit(self, ax, az):
        """Karte unter dem Mauszeiger -> (Slot, Waffe) oder None."""
        for slot, wi, x, z, hh in self.rects:
            if abs(ax - x) <= 0.27 and abs(az - z) <= hh:
                return (slot, wi)
        return None

    def update(self, loadout, hover=None):
        for slot, wi, frame, lbl in self.cards:
            sel = loadout[slot] == wi
            hov = hover == (slot, wi)
            frame.setColor(*((1.0, 0.85, 0.2, 1.0) if sel else
                             (0.45, 0.75, 1.0, 1.0) if hov else (0.38, 0.41, 0.46, 1.0)))
            lbl.setFg((1, 0.9, 0.3, 1) if sel else (0.6, 0.85, 1, 1) if hov else (1, 1, 1, 1))

    def show(self):
        self.root.show()

    def hide(self):
        self.root.hide()

    def destroy(self):
        for t in self.texts:
            t.destroy()
        self.root.removeNode()


# ------------------------------------------------------------------ Setup-Seite (Karte, Modus, Zeitlimit)
class HitRect:
    """Anklickbarer Bereich ohne Text (Kartenkachel, Knopf, Slider). Verhält sich im Menü wie Hot."""

    def __init__(self, x0, x1, z0, z1, action, hover=None):
        self.x0, self.x1, self.z0, self.z1 = x0, x1, z0, z1
        self.action, self.hover, self.on = action, hover, False

    def hit(self, ax, az):
        return self.action is not None and self.x0 <= ax <= self.x1 and self.z0 <= az <= self.z1

    def set(self, on):
        if on != self.on:
            self.on = on
            if self.hover is not None:
                self.hover(on)

    def destroy(self):
        pass


def json_map_preview(path, n=192):
    """Vorschaubild einer Editor-Karte (.json) von oben: Gelände nach Höhe, dazu Blöcke, Häuser, Türme, Teiche, Felsen
    -> (Breite, Höhe, RGB-Bytes) im 16:9-Format (Mittelstreifen der quadratischen Karte)."""
    with open(path, encoding="utf-8") as f:
        md = sanitize_map(json.load(f))
    tr = md.get("terrain")
    sc = md.get("size", MAP_WORLD) / n
    img = bytearray(n * n * 3)

    def put(px, py, col):
        if 0 <= px < n and 0 <= py < n:
            k = (py * n + px) * 3
            img[k], img[k + 1], img[k + 2] = (int(min(1.0, max(0.0, c)) * 255) for c in col)

    cm = TriMesh(*md["mesh"]["coll"]) if md.get("mesh") else None

    def hgt(x, y):
        if cm is not None:
            z = cm.top(x, y)
            return -50.0 if z is None else z
        if tr is None:
            return 0.0
        nn, st, z = tr
        fx, fy = min(nn - 1.000001, max(0.0, x / st)), min(nn - 1.000001, max(0.0, y / st))
        i, j = int(fx), int(fy)
        tx, ty = fx - i, fy - j
        k = j * nn + i
        a = z[k] + (z[k + 1] - z[k]) * tx
        b = z[k + nn] + (z[k + nn + 1] - z[k + nn]) * tx
        return a + (b - a) * ty
    for py in range(n):
        for px in range(n):
            x, y = (px + 0.5) * sc, (py + 0.5) * sc
            h = hgt(x, y)
            if h < -40.0:
                put(px, n - 1 - py, (0.09, 0.10, 0.12))
                continue
            hx = hgt(x + 2.0, y) - hgt(x - 2.0, y)                   # Hangschattierung
            light = 0.5 + 0.12 * (hgt(x - 2.0, y) - hgt(x + 2.0, y)) + 0.05 * (hgt(x, y - 2.0) - hgt(x, y + 2.0))
            light = min(0.75, max(0.15, light))                            # keine ausgebrannten oder schwarzen Kanten
            if md.get("steep"):                                               # Klippenkarte: Tal grün, Hänge braun, oben grau
                t = min(1.0, max(0.0, (h - 4.0) / 40.0))
                col = (0.30 + 0.25 * t, 0.42 + 0.0 * t - 0.02 * t, 0.20 + 0.32 * t) if h < 9.0 else (0.42 + 0.2 * t, 0.37 + 0.2 * t, 0.30 + 0.25 * t)
            elif h > 1.8:
                col = (0.46 + 0.015 * h, 0.40 + 0.012 * h, 0.33 + 0.01 * h)       # Fels
            elif h < -1.0:
                col = (0.18, 0.28, 0.42)
            else:
                col = (0.30, 0.42, 0.20)
            put(px, n - 1 - py, tuple(c * (0.55 + light) for c in col))
    pw = lambda v: int(v / sc)                                        # noqa: E731

    def rect(x0, y0, x1, y1, col):
        for py in range(pw(y0), pw(y1) + 1):
            for px in range(pw(x0), pw(x1) + 1):
                put(px, n - 1 - py, col)
    for x, y, r in md.get("ponds") or ():
        for py in range(pw(y - r), pw(y + r) + 1):
            for px in range(pw(x - r), pw(x + r) + 1):
                if math.hypot((px + 0.5) * sc - x, (py + 0.5) * sc - y) <= r:
                    put(px, n - 1 - py, (0.20, 0.38, 0.62))
    for x, y, r in md.get("rocks") or ():
        rect(x - r * 0.6, y - r * 0.6, x + r * 0.6, y + r * 0.6, (0.38, 0.38, 0.40))
    for b in md.get("blocks") or ():
        c = b["c"]
        k = 0.8 + min(0.35, b["h"] * 0.03)
        rect(b["x0"], b["y0"], b["x1"], b["y1"], tuple(v * k for v in c))
    for hs in md.get("houses") or ():
        rect(hs["x"] - hs["w"] / 2, hs["y"] - hs["d"] / 2, hs["x"] + hs["w"] / 2, hs["y"] + hs["d"] / 2,
             tuple(min(1.0, v * 1.15) for v in hs["c"]))
    for t in md.get("towers") or ():
        rect(t["x"] - 2.5, t["y"] - 2.5, t["x"] + 2.5, t["y"] + 2.5, (0.62, 0.60, 0.55))
    if cm is not None:                                        # Netzkarte (Blood Gulch): auf die Fläche zuschneiden, 16:9
        void = (0.09, 0.10, 0.12)
        vb = bytes(int(c * 255) for c in void)
        xs, ys = [], []
        for py in range(n):
            row = img[py * n * 3:(py + 1) * n * 3]
            for px in range(n):
                if row[px * 3:px * 3 + 3] != vb:
                    xs.append(px)
                    ys.append(py)
        if xs:                                                # Längsachse waagerecht drehen, dann auf 16:9 zuschneiden
            mx_, my_ = sum(xs) / len(xs), sum(ys) / len(ys)
            sxx = sum((x - mx_) ** 2 for x in xs)
            syy = sum((y - my_) ** 2 for y in ys)
            sxy = sum((x - mx_) * (y - my_) for x, y in zip(xs, ys))
            th = 0.5 * math.atan2(2 * sxy, sxx - syy)         # Richtung der Hauptachse
            ct, st = math.cos(th), math.sin(th)
            us = [(x - mx_) * ct + (y - my_) * st for x, y in zip(xs, ys)]
            vs = [-(x - mx_) * st + (y - my_) * ct for x, y in zip(xs, ys)]
            uc, vc = (min(us) + max(us)) / 2, (min(vs) + max(vs)) / 2
            hw = max((max(us) - min(us)) * 0.56, (max(vs) - min(vs)) * 0.56 * 16 / 9)
            hh = hw * 9 / 16
            ow, oh = 256, 144
            out = bytearray(ow * oh * 3)
            for oy in range(oh):
                v = vc - hh + (oy + 0.5) / oh * 2 * hh
                for ox in range(ow):
                    u = uc - hw + (ox + 0.5) / ow * 2 * hw
                    sx, sy = int(mx_ + u * ct - v * st), int(my_ + u * st + v * ct)
                    k = (oy * ow + ox) * 3
                    if 0 <= sx < n and 0 <= sy < n:
                        out[k:k + 3] = img[(sy * n + sx) * 3:(sy * n + sx) * 3 + 3]
                    else:
                        out[k:k + 3] = bytes((22, 24, 28))
            return ow, oh, bytes(out)
    if md.get("size", MAP_WORLD) > 250:                       # grosse Karte: ganz zeigen (16:9 mit dunklen Seitenstreifen)
        w2 = n * 16 // 9
        out = bytearray(bytes((22, 24, 28)) * (w2 * n))
        x0 = (w2 - n) // 2
        for py in range(n):
            out[(py * w2 + x0) * 3:(py * w2 + x0 + n) * 3] = img[py * n * 3:(py + 1) * n * 3]
        return w2, n, bytes(out)
    h = n * 9 // 16
    r0 = (n - h) // 2
    return n, h, bytes(img[r0 * n * 3:(r0 + h) * n * 3])


def map_preview_rgb(key):
    """Vorschaubild einer Karte als (Breite, Höhe, RGB-Bytes) oder None. key: Name im Bilderspeicher oder
    ("mm", Pfad) = Minimap einer .mcmap-Datei (Mittelstreifen im 16:9-Format)."""
    try:
        if isinstance(key, str):
            ent = MAP_PREVIEWS.get(key)
            if ent is None:
                return None
            w, h, b = ent
            return w, h, zlib.decompress(base64.b64decode(b))
        if isinstance(key, tuple) and key[0] == "jm":
            return json_map_preview(key[1])
        if isinstance(key, tuple) and key[0] == "mm":
            md, _raw = mc_mapdata(key[1])
            n, mm = md["mc"]["meta"]["mm"], md["mc"]["minimap"]
            h = n * 9 // 16
            r0 = (n - h) // 2
            return n, h, bytes(mm[r0 * n * 3:(r0 + h) * n * 3])
    except Exception:
        return None
    return None


class SetupPage:
    """Erste Setup-Seite: Karten mit Vorschaubild, Spielmodus, Zeitlimit-Slider und der Knopf für die
    weiteren Einstellungen. layout() ruft nur rect/text/image/hit auf - so lässt sich das Layout auch
    ohne Panda3D zeichnen und prüfen (siehe Tests); die Methoden hier bauen die echten Knoten."""
    PER_PAGE = 4                                   # Karten pro Seite (mehr: Pfeile zum Blättern)
    X0, X1 = -0.64, 0.64                           # Breite des Inhalts
    SL0, SL1, SLZ = -0.62, 0.62, -0.47             # Slider: Anfang, Ende, Höhe
    SEL, HOV, IDLE = (1.0, 0.62, 0.14, 1.0), (1.0, 0.72, 0.30, 1.0), (0.24, 0.30, 0.40, 1.0)
    BTN, BTN_H = BTN_C, BTN_HC
    GO, GO_H = START_BTN, START_BTN_HOT
    MODE_ON, MODE_OFF = (0.34, 0.30, 0.22, 0.98), (0.10, 0.12, 0.15, 0.70)
    CARD_BG = (0.06, 0.08, 0.11, 0.96)
    GREY, WHITE, YELLOW = (0.50, 0.55, 0.61, 1.0), (0.91, 0.94, 0.97, 1.0), (1.0, 0.62, 0.14, 1.0)
    DIM = (0.42, 0.47, 0.52, 1.0)

    def __init__(self, game):
        self.g = game
        self.hover = None
        self.key = None
        self.nodes = {}
        self.txts = set()
        self.ents = game.setup_entries()
        self.page = max(0, min(game.map_page, (len(self.ents) - 1) // self.PER_PAGE))
        game.map_page = self.page
        self.layout()
        self.update(True)

    # ------------------------------------------------------------ Zustand
    def sel_index(self):
        p = self.g.cfg.get("map")
        return next((i for i, e in enumerate(self.ents) if e[1] == p), 0)

    def mode_off(self, k):
        return self.g.cfg_is_mc() and MODES[k] not in MC_MODES

    def vx(self, v):
        return self.SL0 + (v - LIMIT_MIN) / float(LIMIT_MAX - LIMIT_MIN) * (self.SL1 - self.SL0)

    @staticmethod
    def minutes(v):
        return f"{v} Minute" if v == 1 else f"{v} Minuten"

    def style(self, i):
        """Farbe des Elements i (Rahmen, Knopf, Text) im aktuellen Zustand."""
        c, hov = self.g.cfg, self.hover
        tag, num = i.rstrip("0123456789"), i[len(i.rstrip("0123456789")):]
        if tag in ("cf", "cn"):
            sel = self.page * self.PER_PAGE + int(num) == self.sel_index()
            if tag == "cn":
                return self.YELLOW if sel else self.WHITE
            return self.SEL if sel else (self.HOV if hov == "card" + num else self.IDLE)
        if tag in ("mf", "mb", "mt"):
            k = int(num)
            on, off, h = MODES[k] == c["mode"], self.mode_off(k), hov == "mode" + num
            if tag == "mf":
                return self.SEL if on and not off else (self.HOV if h and not off else (0.0, 0.0, 0.0, 0.0))
            if tag == "mb":
                return self.MODE_OFF if off else (self.MODE_ON if on else (self.BTN_H if h else self.BTN))
            return self.DIM if off else (self.YELLOW if on else (Hot.ON if h else Hot.BASE))
        if i == "fill":
            return (1.0, 0.62, 0.14, 1.0)
        if i.startswith(("b_", "t_")):
            name = i[2:]
            h = hov == "btn_" + name
            if i[0] == "b":
                return (self.GO_H if h else self.GO) if name == "go" else (self.BTN_H if h else self.BTN)
            return Hot.ON if h else Hot.BASE
        if i == "knob":
            return (1.0, 1.0, 0.78, 1.0) if (hov == "slider" or self.g.slider_drag) else (1.0, 0.85, 0.4, 1.0)
        return self.WHITE

    # ------------------------------------------------------------ Layout (nur rect/text/image/hit)
    def layout(self):
        g = self.g
        X0, X1 = self.X0, self.X1
        first = self.page * self.PER_PAGE
        vis = self.ents[first:first + self.PER_PAGE]
        n = len(vis)
        self.text("title", self.title_label(), 0, 0.395, 0.075,
                  (1.0, 0.78, 0.3, 1.0))
        # --- Karten
        cw = 0.62 if n <= 2 else 0.46
        total = n * cw + (n - 1) * 0.08
        iw = cw - 0.04
        ih = iw * 9 / 16
        ch = 0.02 + ih + 0.115
        zt = (0.31 - 0.151) / 2 + ch / 2
        small = cw < 0.5
        for i, (name, path, cap, key) in enumerate(vis):
            xc = -total / 2 + cw / 2 + i * (cw + 0.08)
            gi = first + i
            self.rect(f"cf{i}", xc - cw / 2 - 0.012, xc + cw / 2 + 0.012, zt - ch - 0.012, zt + 0.012)
            self.rect(None, xc - cw / 2, xc + cw / 2, zt - ch, zt, self.CARD_BG)
            iz1 = zt - 0.02
            self.image(key, xc - iw / 2, xc + iw / 2, iz1 - ih, iz1, name)
            if gi < 9:                                                  # Ziffer der Zifferntaste
                self.rect(None, xc - iw / 2 + 0.01, xc - iw / 2 + 0.062, iz1 - 0.068, iz1 - 0.01, (0, 0, 0, 0.6))
                self.text(None, str(gi + 1), xc - iw / 2 + 0.036, iz1 - 0.055, 0.042, self.WHITE)
            self.text(f"cn{i}", name, xc, iz1 - ih - 0.058, 0.042 if small else 0.05)
            self.text(None, cap, xc, iz1 - ih - 0.097, 0.026 if small else 0.03, self.GREY)
            self.hit(f"card{i}", xc - cw / 2 - 0.012, xc + cw / 2 + 0.012, zt - ch - 0.012, zt + 0.012,
                     lambda gi=gi: g.setup_pick(gi))
        if len(self.ents) > self.PER_PAGE:                              # Blättern bei vielen Karten
            for sgn, ch_, act in ((-1, "<", -1), (1, ">", 1)):
                xa = sgn * (total / 2 + 0.11)
                self.rect(f"pg{act}", xa - 0.05, xa + 0.05, zt - ch / 2 - 0.08, zt - ch / 2 + 0.08, self.BTN)
                self.text(None, ch_, xa, zt - ch / 2 - 0.03, 0.09, self.WHITE)
                self.hit(f"pgh{act}", xa - 0.05, xa + 0.05, zt - ch / 2 - 0.08, zt - ch / 2 + 0.08,
                         lambda a=act: g.setup_turn(a))
        # --- Modus
        self.text(None, "MODUS", X0, -0.205, 0.034, self.GREY, "l")
        n_m, gap_m = len(MODES), 0.04
        wm = (X1 - X0 - gap_m * (n_m - 1)) / n_m
        for k, mode in enumerate(MODES):
            x0 = X0 + k * (wm + gap_m)
            x1 = x0 + wm
            self.rect(f"mf{k}", x0 - 0.008, x1 + 0.008, -0.343, -0.237)
            self.rect(f"mb{k}", x0, x1, -0.335, -0.245)
            self.text(f"mt{k}", MODE_NAMES[mode], (x0 + x1) / 2, -0.305, 0.045)
            self.hit(f"mode{k}", x0, x1, -0.335, -0.245, lambda m=mode: g.setup_mode(m))
        # --- Zeitlimit-Slider
        v = int(g.cfg["limit"])
        self.text(None, "ZEITLIMIT", X0, -0.40, 0.034, self.GREY, "l")
        self.text("val", self.minutes(v), X1, -0.40, 0.05, self.YELLOW, "r")
        self.rect(None, self.SL0, self.SL1, self.SLZ - 0.007, self.SLZ + 0.007, (0.16, 0.22, 0.30, 1.0))
        for tv in (1, 15, 30, 45, 60):
            tx = self.vx(tv)
            self.rect(None, tx - 0.002, tx + 0.002, self.SLZ - 0.034, self.SLZ - 0.014, (0.45, 0.52, 0.60, 1.0))
            self.text(None, str(tv), tx, self.SLZ - 0.075, 0.03, self.GREY)
        self.rect("fill", self.SL0, self.vx(v), self.SLZ - 0.007, self.SLZ + 0.007, (1.0, 0.62, 0.14, 1.0))
        self.rect("knob", self.vx(v) - 0.028, self.vx(v) + 0.028, self.SLZ - 0.028, self.SLZ + 0.028, rot=45.0)
        self.hit("slider", self.SL0 - 0.05, self.SL1 + 0.05, self.SLZ - 0.06, self.SLZ + 0.06, g.slider_begin)
        # --- Knöpfe
        self.bottom_buttons(X0, X1)
        if g.menu_msg:
            self.text("msg", g.menu_msg, 0, -0.885, 0.034, (1.0, 0.5, 0.35, 1.0))
        elif g.cfg["mode"] == "experimental":
            self.text(None, "Experimental startet Robins Spielversion - dort gelten ihre eigenen Regeln",
                      0, -0.885, 0.03, self.YELLOW)
        else:
            self.text(None, "Tasten:  Ziffern = Karte    Pfeile = Modus und Zeitlimit    W = Weitere    Enter = Start",
                      0, -0.885, 0.028, self.GREY)

    def title_label(self):
        return "Einzelspieler" if self.g.setup_for == "single" else "Spiel hosten"

    def bottom_buttons(self, X0, X1):
        g = self.g
        self.button("more", X0, X1, -0.69, -0.605, "Weitere Einstellungen   (W)", 0.052, g.setup_more)
        self.button("back", X0, -0.02, -0.805, -0.72, "Zurück   (Esc)", 0.052, g.on_escape)
        self.button("go", 0.02, X1, -0.805, -0.72, "Start   (Enter)", 0.052, lambda: g.begin_game(g.setup_for))

    def button(self, name, x0, x1, z0, z1, label, scale, action):
        self.rect("b_" + name, x0, x1, z0, z1)
        self.text("t_" + name, label, (x0 + x1) / 2, z0 + 0.028, scale)
        self.hit("btn_" + name, x0, x1, z0, z1, action)

    # ------------------------------------------------------------ Knoten (Panda3D)
    def rect(self, i, x0, x1, z0, z1, col=None, rot=0.0):
        col = col if col is not None else self.style(i)
        cm = CardMaker(i or "r")
        if (i or "").endswith("fill"):          # Einheitsbreite, wird zum Ändern skaliert (Ursprung = linker Rand)
            cm.setFrame(0.0, 1.0, z0, z1)
        elif (i or "").endswith("knob"):        # um den Ursprung zentriert, wird zum Ändern verschoben
            cm.setFrame(x0 - (x0 + x1) / 2, x1 - (x0 + x1) / 2, z0 - (z0 + z1) / 2, z1 - (z0 + z1) / 2)
        else:
            cm.setFrame(x0, x1, z0, z1)
        nd = self.g.aspect2d.attachNewNode(cm.generate())
        nd.setColor(*col)
        nd.setTransparency(TransparencyAttrib.MAlpha)
        if (i or "").startswith(("b_", "mb", "lb", "rb", "vb")):
            btn3d(nd)
        if (i or "").endswith("fill"):
            nd.setPos(x0, 0, 0)
            nd.setSx(max(0.001, x1 - x0))
        elif (i or "").endswith("knob"):
            nd.setPos((x0 + x1) / 2, 0, (z0 + z1) / 2)
        if rot:
            nd.setR(rot)
        self.g.menu_items.append(Deco(nd))
        if i:
            self.nodes[i] = nd
        return nd

    def text(self, i, s, x, z, scale, col=None, al="c"):
        col = col if col is not None else self.style(i)
        t = OnscreenText(text=s, pos=(x, z), scale=scale, fg=col, shadow=(0, 0, 0, 0.8), mayChange=True,
                         font=BOLD_FONT if (i or "").startswith(("t_", "mt", "lt", "rt", "vt")) else None,
                         align={"c": TextNode.ACenter, "l": TextNode.ALeft, "r": TextNode.ARight}[al])
        self.g.menu_items.append(t)
        if i:
            self.nodes[i] = t
            self.txts.add(i)
        return t

    def image(self, key, x0, x1, z0, z1, name=""):
        cm = CardMaker("vorschau")
        cm.setFrame(x0, x1, z0, z1)
        nd = self.g.aspect2d.attachNewNode(cm.generate())
        tex = self.g.preview_texture(key)
        if tex is not None:
            nd.setTexture(tex)
            nd.setColor(1, 1, 1, 1)
        else:
            nd.setColor(0.12, 0.18, 0.26, 1.0)
        self.g.menu_items.append(Deco(nd))
        if tex is None:
            self.text(None, "Eigene Karte", (x0 + x1) / 2, (z0 + z1) / 2 - 0.015, 0.045, self.GREY)

    def hit(self, i, x0, x1, z0, z1, action):
        self.g.menu_lines.append(HitRect(x0, x1, z0, z1, action, lambda on, i=i: self.set_hover(i, on)))

    # ------------------------------------------------------------ Änderungen
    def set_hover(self, i, on):
        if on:
            self.hover = i
        elif self.hover == i:
            self.hover = None
        self.update()

    def update(self, force=False):
        c = self.g.cfg
        key = (c.get("map"), c["mode"], int(c["limit"]), self.hover, self.g.slider_drag)
        if force or key != self.key:
            self.key = key
            self.sync()

    def sync(self):
        v = int(self.g.cfg["limit"])
        for i, nd in self.nodes.items():
            if i in ("fill", "knob", "val", "title", "msg"):
                continue
            col = self.style(i)
            if i in self.txts:
                nd.setFg(col)
            else:
                nd.setColor(*col)
        x = self.vx(v)
        if "fill" in self.nodes:
            self.nodes["fill"].setSx(max(0.001, x - self.SL0))
        if "knob" in self.nodes:
            self.nodes["knob"].setPos(x, 0, self.SLZ)
            self.nodes["knob"].setColor(*self.style("knob"))
        if "val" in self.nodes:
            self.nodes["val"].setText(self.minutes(v))



class EndSetupPage(SetupPage):
    """Karte, Modus und Zeitlimit der nächsten Runde - dieselbe Seite wie beim Hosten, aber im Rundenendbildschirm
    eingebettet: 'Übernehmen' ändert die laufende Sitzung, ohne dass jemand getrennt wird."""

    def title_label(self):
        return "Rundeneinstellungen"

    def mode_off(self, k):
        return MODES[k] == "experimental" or SetupPage.mode_off(self, k)

    def bottom_buttons(self, X0, X1):
        g = self.g
        self.button("more", X0, X1, -0.69, -0.605, "Weitere Einstellungen   (W)", 0.052, g.end_cfg_more)
        self.button("back", X0, -0.02, -0.805, -0.72, "Abbrechen   (Esc)", 0.052, g.end_cfg_cancel)
        self.button("go", 0.02, X1, -0.805, -0.72, "Übernehmen", 0.052, g.end_cfg_apply)


class CharPreview:
    """3D-Vorschau des Charakters im Menü: eigene Kamera und eigener Anzeigebereich (über dem 2D-Menü).
    Die Figur steht still und lässt sich mit gedrückter linker Maustaste drehen; sie wird bei jeder Änderung neu aufgebaut."""

    def __init__(self, game, x0, x1, z0, z1):
        self.g = game
        self.box = (x0, x1, z0, z1)
        self.root = NodePath("char_prev")
        self.lens = PerspectiveLens()
        self.lens.setNearFar(0.3, 30.0)
        cam = Camera("char_cam")
        cam.setLens(self.lens)
        self.cam = self.root.attachNewNode(cam)
        cam.setScene(self.root)
        self.cam.setPos(0, 3.5, 0.98)                # Kamera vor der Figur (sie blickt nach +y)
        self.cam.lookAt(0, 0, 0.93)
        self.dr = game.win.makeDisplayRegion()
        self.dr.setSort(30)                       # über dem 2D-Menü
        self.dr.setClearDepthActive(True)
        self.dr.setCamera(self.cam)
        self.pivot = self.root.attachNewNode("pivot")
        m = Mesh(lit=False)                       # Podest
        n = 28
        for i in range(n):
            a0, a1 = 2 * math.pi * i / n, 2 * math.pi * (i + 1) / n
            c = (0.17, 0.24, 0.34) if i % 2 else (0.14, 0.20, 0.30)
            m.tri((0, 0, -0.02), (math.cos(a0) * 0.62, math.sin(a0) * 0.62, -0.02),
                  (math.cos(a1) * 0.62, math.sin(a1) * 0.62, -0.02), c, ref=(0, 0, -1.0))
            m.tri((math.cos(a0) * 0.62, math.sin(a0) * 0.62, -0.02), (math.cos(a0) * 0.62, math.sin(a0) * 0.62, -0.08),
                  (math.cos(a1) * 0.62, math.sin(a1) * 0.62, -0.02), (0.10, 0.14, 0.2), ref=(0, 0, 0.5))
            m.tri((math.cos(a1) * 0.62, math.sin(a1) * 0.62, -0.02), (math.cos(a0) * 0.62, math.sin(a0) * 0.62, -0.08),
                  (math.cos(a1) * 0.62, math.sin(a1) * 0.62, -0.08), (0.10, 0.14, 0.2), ref=(0, 0, 0.5))
        self.root.attachNewNode(m.node("podest")).setTwoSided(True)
        self.view = None
        self.key = None
        self.ang = 20.0                              # leicht seitlich: Gewehr und Rucksack sind sichtbar
        self.drag = False
        self.lastx = 0.0
        self.pivot.setH(self.ang)
        self.place()

    def place(self):
        """Anzeigebereich passend zur Fenstergrösse (die Menü-Koordinaten laufen bei breiten Fenstern über +-Seitenverhältnis)."""
        a = max(0.2, float(self.g.getAspectRatio()))
        xr, zr = max(1.0, a), max(1.0, 1.0 / a)
        x0, x1, z0, z1 = self.box
        l, r = (x0 + xr) / (2 * xr), (x1 + xr) / (2 * xr)
        b, t = (z0 + zr) / (2 * zr), (z1 + zr) / (2 * zr)
        self.dr.setDimensions(l, r, b, t)
        asp = (r - l) / max(1e-4, (t - b)) * a
        vf = 36.0
        hf = math.degrees(2 * math.atan(math.tan(math.radians(vf / 2)) * asp))
        self.lens.setFov(hf, vf)
        self.asp = a

    def set_look(self, code):
        key = (code, self.g.my_id if getattr(self.g, "my_id", None) is not None else 0)
        if key == self.key:
            return
        self.key = key
        if self.view is not None:
            self.view.root.removeNode()
        p = SimpleNamespace(pid=key[1], look=code, x=0.0, y=0.0, z=0.0, heading=0.0, heli=-1, hp=100.0, crouch=0.0,
                            moving=False, lean=0.0, cur=[i for i, w_ in enumerate(WEAPONS) if w_.name == "Sturmgewehr"][0])
        self.view = PlayerView(p)
        self.view.root.reparentTo(self.pivot)
        self.fake = p

    def tick(self, dt):
        if abs(self.asp - float(self.g.getAspectRatio())) > 1e-3:
            self.place()
        down, m = False, self.g.mouse_2d()
        try:
            down = bool(self.g.mouseWatcherNode.is_button_down(MouseButton.one()))
        except Exception:
            pass
        x0, x1, z0, z1 = self.box
        if down and m is not None:
            if not self.drag and x0 <= m[0] <= x1 and z0 <= m[1] <= z1:
                self.drag, self.lastx = True, m[0]               # Ziehen beginnt nur im Vorschaufeld
            elif self.drag:
                self.ang = (self.ang + (m[0] - self.lastx) * 260.0) % 360.0
                self.lastx = m[0]
                self.pivot.setH(self.ang)
        if not down:
            self.drag = False
        if self.view is not None:
            self.view.update(self.fake, dt)

    def destroy(self):
        try:
            self.g.win.removeDisplayRegion(self.dr)
        except Exception:
            pass
        self.root.removeNode()


class CharPage(SetupPage):
    """Hauptmenü 'Charakter personalisieren': links die sich drehende Figur, rechts je Eigenschaft ein Auswahlfeld
    mit Pfeilen. Das Aussehen wird gespeichert, ist im Spiel für dich sichtbar (Hände, Ärmel) und wird an alle
    Mitspieler geschickt."""
    COLS = ((-0.17, 0.47), (0.53, 1.17))
    PER_COL = 7

    def __init__(self, game):
        self.g = game
        self.hover = None
        self.key = None
        self.nodes = {}
        self.txts = set()
        self.prev = CharPreview(game, -1.17, -0.27, -0.80, 0.72)
        self.layout()
        self.update(True)

    def destroy(self):
        self.prev.destroy()

    def tick(self, dt):
        self.prev.tick(dt)

    def vals(self, k):
        return LOOK_OPTS[k][2]

    def cur(self, k):
        return int(self.g.look_code[k])

    def style(self, i):
        hov = self.hover
        tag, num = i.rstrip("0123456789"), i[len(i.rstrip("0123456789")):]
        if tag in ("lb", "rb"):
            return self.BTN_H if hov == ("L" if tag == "lb" else "R") + num else self.BTN
        if tag == "vb":
            return (0.20, 0.30, 0.45, 0.95) if hov == "V" + num else (0.11, 0.18, 0.28, 0.92)
        if tag in ("lt", "rt"):
            return Hot.ON if hov == ("L" if tag == "lt" else "R") + num else Hot.BASE
        if tag == "vt":
            return self.YELLOW if hov == "V" + num else self.WHITE
        if i.startswith(("b_", "t_")):
            h = hov == "btn_" + i[2:]
            return (self.BTN_H if h else self.BTN) if i[0] == "b" else (Hot.ON if h else Hot.BASE)
        return self.WHITE

    def layout(self):
        g = self.g
