class MorePage(SetupPage):
    """Weitere Einstellungen einer Runde: Monsterdichte (5 Stufen), Tomahawk an/aus und Schieberegler für die Zahlen."""
    SLIDERS = (("cd", "TOMAHAWK-ABKLINGZEIT", 0, 600, 10, (0, 120, 240, 360, 480, 600), strike_cd_label, 0.14),
               ("regen", "GESUNDHEITSREGENERATION", 0.0, 10.0, 0.5, (0, 2, 5, 10), regen_label, -0.07),
               ("resp", "RESPAWN-ZEIT", 0, 30, 1, (0, 5, 10, 20, 30), respawn_label, -0.28))

    def __init__(self, game):
        self.sl = {d[0]: d for d in self.SLIDERS}
        SetupPage.__init__(self, game)

    # ---- Zustand
    def tm_on(self):
        return bool(self.g.cfg.get("tomahawk", True))

    def lvl(self):
        return mob_level_of(self.g.cfg["mobs"])

    def sx(self, key, v):
        _k, _l, lo, hi = self.sl[key][:4]
        return self.SL0 + (v - lo) / float(hi - lo) * (self.SL1 - self.SL0)

    def style(self, i):
        hov = self.hover
        mc = self.g.cfg_is_mc()
        tag, num = i.rstrip("0123456789"), i[len(i.rstrip("0123456789")):]
        if tag in ("lf", "lb", "lt"):                      # Monsterstufe
            k = int(num)
            on, h = k == self.lvl(), hov == "lv" + num
            off = mc and k > 0
            if tag == "lf":
                return self.SEL if on and not off else (self.HOV if h and not off else (0.0, 0.0, 0.0, 0.0))
            if tag == "lb":
                return self.MODE_OFF if off else (self.MODE_ON if on else (self.BTN_H if h else self.BTN))
            return self.DIM if off else (self.YELLOW if on else (Hot.ON if h else Hot.BASE))
        if tag in ("tf", "tb", "tt"):                      # Tomahawk an / aus
            k = int(num)
            on, h = (k == 0) == self.tm_on(), hov == "tm" + num
            if tag == "tf":
                return self.SEL if on else (self.HOV if h else (0.0, 0.0, 0.0, 0.0))
            if tag == "tb":
                return self.MODE_ON if on else (self.BTN_H if h else self.BTN)
            return self.YELLOW if on else (Hot.ON if h else Hot.BASE)
        for key in self.sl:
            if i.startswith(key + "_"):
                dim = key == "cd" and not self.tm_on()
                kind = i[len(key) + 1:]
                if kind == "fill":
                    return (0.35, 0.37, 0.40, 1.0) if dim else (1.0, 0.62, 0.14, 1.0)
                if kind == "knob":
                    if dim:
                        return (0.5, 0.52, 0.55, 1.0)
                    return (1.0, 1.0, 0.78, 1.0) if (hov == "sl_" + key or self.g.slider_drag == key) else (1.0, 0.85, 0.4, 1.0)
                if kind == "val":
                    return self.DIM if dim else self.YELLOW
                return self.WHITE
        if i.startswith(("b_", "t_")):
            h = hov == "btn_" + i[2:]
            return (self.BTN_H if h else self.BTN) if i[0] == "b" else (Hot.ON if h else Hot.BASE)
        return self.WHITE

    def value(self, key):
        v = self.g.cfg[key]
        return int(v) if key != "regen" else float(v)

    # ---- Layout
    def layout(self):
        g, X0, X1 = self.g, self.X0, self.X1
        self.text("title", "Weitere Einstellungen", 0, 0.80, 0.075, (1.0, 0.78, 0.3, 1.0))
        self.text(None, "MONSTER" + ("   (auf Minecraft-Karten gibt es keine)" if g.cfg_is_mc() else ""), X0, 0.64, 0.034, self.GREY, "l")
        n = len(MOB_LEVELS)
        bw = (X1 - X0 - 0.02 * (n - 1)) / n
        for k, (name, _f) in enumerate(MOB_LEVELS):
            x0 = X0 + k * (bw + 0.02)
            self.rect(f"lf{k}", x0 - 0.008, x0 + bw + 0.008, 0.49, 0.605)
            self.rect(f"lb{k}", x0, x0 + bw, 0.497, 0.597)
            self.text(f"lt{k}", name, x0 + bw / 2, 0.525, 0.048)
            self.hit(f"lv{k}", x0, x0 + bw, 0.497, 0.597, lambda k=k: g.set_cfg("mobs", k))
        self.text(None, "TOMAHAWK", X0, 0.40, 0.034, self.GREY, "l")
        for k, name in enumerate(("An", "Aus")):
            x0, x1 = (X0, -0.01) if k == 0 else (0.01, X1)
            self.rect(f"tf{k}", x0 - 0.008, x1 + 0.008, 0.245, 0.355)
            self.rect(f"tb{k}", x0, x1, 0.253, 0.347)
            self.text(f"tt{k}", name, (x0 + x1) / 2, 0.275, 0.05)
            self.hit(f"tm{k}", x0, x1, 0.253, 0.347, lambda k=k: g.set_cfg("tomahawk", k == 0))
        for key, label, lo, hi, step, ticks, fmt, z in self.SLIDERS:
            self.text(None, label, X0, z, 0.034, self.GREY, "l")
            v = self.value(key)
            self.text(key + "_val", fmt(v), X1, z, 0.045, self.style(key + "_val"), "r")
            zl = z - 0.07
            self.rect(None, self.SL0, self.SL1, zl - 0.007, zl + 0.007, (0.16, 0.22, 0.30, 1.0))
            for tv in ticks:
                tx = self.sx(key, tv)
                self.rect(None, tx - 0.002, tx + 0.002, zl - 0.032, zl - 0.014, (0.45, 0.52, 0.60, 1.0))
                self.text(None, f"{tv:g}", tx, zl - 0.07, 0.027, self.GREY)
            self.rect(key + "_fill", self.SL0, self.sx(key, v), zl - 0.007, zl + 0.007)
            self.rect(key + "_knob", self.sx(key, v) - 0.026, self.sx(key, v) + 0.026, zl - 0.026, zl + 0.026, rot=45.0)
            self.hit("sl_" + key, self.SL0 - 0.05, self.SL1 + 0.05, zl - 0.06, zl + 0.06,
                     lambda key=key: g.slider_begin(key))
        self.rect("b_done", X0, X1, -0.745, -0.66)
        self.text("t_done", "Fertig   (Esc)", 0, -0.717, 0.052)
        self.hit("btn_done", X0, X1, -0.745, -0.66, g.on_escape)
        self.text(None, "Tasten:  1-5 = Monster    T = Tomahawk an/aus    Esc = zurück", 0, -0.84, 0.028, self.GREY)

    # ---- Aktualisieren
    def update(self, force=False):
        c = self.g.cfg
        key = (self.lvl(), self.tm_on(), c["cd"], c["regen"], c["resp"], self.hover, self.g.slider_drag, self.g.cfg_is_mc())
        if force or key != self.key:
            self.key = key
            self.sync()

    def sync(self):
        for i, nd in self.nodes.items():
            if i in ("title",) or i.endswith(("_fill", "_knob")):
                continue
            col = self.style(i)
            if i in self.txts:
                nd.setFg(col)
            else:
                nd.setColor(*col)
        for key, label, lo, hi, step, ticks, fmt, z in self.SLIDERS:
            v = self.value(key)
            x = self.sx(key, v)
            zl = z - 0.07
            self.nodes[key + "_fill"].setSx(max(0.001, x - self.SL0))
            self.nodes[key + "_fill"].setColor(*self.style(key + "_fill"))
            self.nodes[key + "_knob"].setPos(x, 0, zl)
            self.nodes[key + "_knob"].setColor(*self.style(key + "_knob"))
            self.nodes[key + "_val"].setText(fmt(v))

    def follow(self, key, mx):
        _k, _l, lo, hi, step = self.sl[key][:5]
        t = max(0.0, min(1.0, (mx - self.SL0) / (self.SL1 - self.SL0)))
        v = round((lo + t * (hi - lo)) / step) * step
        self.g.set_cfg(key, int(v) if key != "regen" else float(v))



