# Alles nur mit der Standardbibliothek (socket, json, threading), nicht blockierend,
# damit das Spiel nie auf das Netz warten muss.
KINDS = ("grunt", "brute", "huntress")          # Index in den Snapshots
STATES = ("idle", "chase", "attack", "dead")
PLAYER_COLORS = [(0.20, 0.35, 0.80), (0.80, 0.25, 0.25), (0.25, 0.70, 0.35), (0.85, 0.70, 0.15),
                 (0.60, 0.30, 0.75), (0.15, 0.70, 0.75), (0.90, 0.50, 0.15), (0.85, 0.85, 0.85)]


def r1(v):
    return round(v, 1)


def r2(v):
    return round(v, 2)


def finite(*vals):
    """True, wenn alle Werte endliche Zahlen sind (JSON erlaubt auch NaN/Infinity)."""
    return all(isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)
               for v in vals)


def local_ip():
    """IP-Adresse dieses Rechners im lokalen Netz (es wird nichts gesendet)."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("10.255.255.255", 1))
        return s.getsockname()[0]
    except OSError:
        return "127.0.0.1"
    finally:
        s.close()


def hamachi_ip():
    """Eigene Hamachi-Adresse (25.x.x.x) oder None. Es wird nichts gesendet."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("25.255.255.254", 1))
        ip = s.getsockname()[0]
        return ip if ip.startswith("25.") else None
    except OSError:
        return None
    finally:
        s.close()


_NETLOG = {"f": None, "t0": time.time()}


def netlog(msg):
    """Hängt eine Zeile an polybash_netz.log (neben dem Spiel) an - zur Fehlersuche bei Verbindungsproblemen."""
    try:
        if _NETLOG["f"] is None:
            base = os.path.dirname(sys.executable if getattr(sys, "frozen", False) else os.path.abspath(__file__))
            path = os.path.join(base, "polybash_netz.log")
            try:
                if os.path.getsize(path) > 500000:
                    os.remove(path)
            except OSError:
                pass
            try:
                _NETLOG["f"] = open(path, "a", encoding="utf-8")
            except OSError:
                import tempfile
                _NETLOG["f"] = open(os.path.join(tempfile.gettempdir(), "polybash_netz.log"), "a", encoding="utf-8")
            import platform
            _NETLOG["f"].write(f"\n[{platform.platform()}, Python {platform.python_version()}]")
            _NETLOG["f"].write(f"\n=== Start {time.strftime('%Y-%m-%d %H:%M:%S')} {VERSION} ===\n")
        t = time.time()
        _NETLOG["f"].write(f"{time.strftime('%H:%M:%S', time.localtime(t))}.{int(t * 1000) % 1000:03d} {msg}\n")
        _NETLOG["f"].flush()
    except Exception:
        pass


_EXC_SEEN = {}


def netlog_exc(tag):
    """Unerwartete Ausnahme im Netzpfad ins Log schreiben (je Ort höchstens 5-mal)."""
    n = _EXC_SEEN.get(tag, 0)
    if n < 5:
        _EXC_SEEN[tag] = n + 1
        import traceback
        netlog(f"FEHLER in {tag}: " + traceback.format_exc().strip().replace("\n", " | "))


class Conn:
    """Nicht blockierende TCP-Verbindung. Eine JSON-Nachricht pro Zeile."""
    MAX_BUF = 6 << 20            # größte Nachricht ~3 MB (die Kartendatei steckt im welcome)

    def __init__(self, sock):
        sock.setblocking(False)
        try:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)   # keine Nagle-Verzögerung
        except OSError:
            pass
        self.sock = sock
        self.rbuf = b""
        self.wbuf = b""
        self.closed = False
        self.error = ""
        self.pid = None              # Spieler-ID (nur beim Host gesetzt, nach "hello")
        self.last_rx = time.time()
        self.rx_bytes = self.tx_bytes = 0

    def send(self, msg):
        self.send_line((json.dumps(msg, separators=(",", ":")) + "\n").encode())

    def send_line(self, line):
        if self.closed:
            return
        self.wbuf += line
        if len(self.wbuf) > self.MAX_BUF // 2:     # Gegenseite liest nicht mehr mit
            self.close("Verbindung zu langsam")

    def flush(self):
        if self.closed or not self.wbuf:
            return
        try:
            n = self.sock.send(self.wbuf)
            self.wbuf = self.wbuf[n:]
            self.tx_bytes += n
        except (BlockingIOError, InterruptedError):
            pass
        except OSError as e:
            self.close(str(e))

    def recv(self):
        """Alle inzwischen vollständig eingetroffenen Nachrichten."""
        out = []
        if not self.closed:
            try:
                for _ in range(64):
                    data = self.sock.recv(65536)
                    if not data:
                        self.close("Verbindung geschlossen")
                        break
                    self.rbuf += data
                    self.rx_bytes += len(data)
                    self.last_rx = time.time()
            except (BlockingIOError, InterruptedError):
                pass
            except OSError as e:
                self.close(str(e))
        if b"\n" in self.rbuf:
            *lines, self.rbuf = self.rbuf.split(b"\n")
            for ln in lines:
                if ln:
                    try:
                        out.append(json.loads(ln))
                    except ValueError:
                        pass
        if len(self.rbuf) > self.MAX_BUF:
            self.close("Nachricht zu gross")
        return out

    def close(self, reason=""):
        if not self.closed:
            self.closed = True
            self.error = reason
            netlog(f"Verbindung zu: '{reason}' (pid={self.pid}, playing={getattr(self, 'playing', False)}, "
                   f"ungesendet={len(self.wbuf)} B, stumm seit {time.time() - self.last_rx:.1f}s)")
            try:
                self.sock.close()
            except OSError:
                pass


class Connector(threading.Thread):
    """Baut die Verbindung im Hintergrund auf, damit das Fenster nicht einfriert."""

    def __init__(self, host, port):
        super().__init__(daemon=True)
        self.addr = (host, port)
        self.conn = None
        self.error = ""
        self.done = False
        self.start()

    def run(self):
        t0 = time.time()
        try:
            self.conn = Conn(socket.create_connection(self.addr, timeout=8.0))
            netlog(f"Client: TCP-Verbindung zu {self.addr[0]}:{self.addr[1]} steht nach {time.time() - t0:.2f}s")
        except (OSError, ValueError) as e:
            self.error = str(e) or "Keine Antwort"
            netlog(f"Client: TCP-Verbindung zu {self.addr[0]}:{self.addr[1]} fehlgeschlagen nach "
                   f"{time.time() - t0:.2f}s: {type(e).__name__}: {e}")
        self.done = True


class JoinAttempt:
    """Verbinden + 'hello' senden + auf 'welcome' des Hosts warten."""

    def __init__(self, host, port, name, look=""):
        self.host, self.name, self.look = host, name, look
        self.thread = Connector(host, port)
        self.conn = None
        self.state = "connecting"      # connecting | waiting | ready | failed
        self.msg = ""
        self.t0 = time.time()
        self.my_id = None
        self.seed = SEED
        self.props = 0
        self.mode = "koth"
        self.limit = 600.0
        self.mobs_on = True
        self.tomahawk = True
        self.map_raw = None            # Kartendatei des Hosts (None = Standardkarte)
        self.extra = []                # Nachrichten, die schon nach dem welcome eintrafen

    def poll(self):
        if self.state == "connecting" and self.thread.done:
            if self.thread.conn is None:
                self.state, self.msg = "failed", "Verbindung fehlgeschlagen: " + self.thread.error
            else:
                self.conn = self.thread.conn
                self.conn.send({"t": "hello", "v": NET_VERSION, "name": self.name, "look": self.look})
                self.state, self.t0 = "waiting", time.time()
                netlog(f"Client: hello gesendet (Version {NET_VERSION}), warte auf welcome")
        if self.state in ("waiting", "ready"):
            self.conn.flush()
            for m in self.conn.recv():
                if not isinstance(m, dict):
                    continue
                if self.state == "ready":
                    self.extra.append(m)
                elif m.get("t") == "welcome":
                    try:
                        self.my_id, self.seed, self.props = int(m["id"]), int(m["seed"]), int(m["props"])
                        self.mode = m.get("mode") if m.get("mode") in MODES else "koth"
                        self.limit = clampf(float(m.get("limit", 600)), 30.0, 7200.0)
                        self.mobs_on = bool(m.get("mobs", 1))
                        self.tomahawk = bool(m.get("tomahawk", 1))
                        self.map_raw = m.get("map") if isinstance(m.get("map"), dict) else None
                        self.state = "ready"
                        netlog(f"Client: welcome von {self.host} nach {time.time() - self.t0:.2f}s (Id {self.my_id}, "
                               f"Modus {self.mode}, Karte {'eigene' if self.map_raw else 'Standard'}, "
                               f"{self.conn.rx_bytes} B empfangen)")
                    except (KeyError, TypeError, ValueError):
                        self.state, self.msg = "failed", "Ungültige Antwort vom Host"
                elif m.get("t") == "refuse":
                    self.state, self.msg = "failed", str(m.get("why", "Abgelehnt"))
                    netlog(f"Client: vom Host abgelehnt: {self.msg}")
                    hv = re.search(r"Host: v(\d+)\.", self.msg)       # "Andere Spielversion (Host: v37.xx)"
                    if (hv and int(hv.group(1)) == EXP_NET_VERSION) or (not hv and "Andere Spielversion" in self.msg):
                        self.state = "exp"                            # Host läuft in Experimental -> dorthin wechseln
                    break
            if self.state == "waiting":
                if self.conn.closed:
                    self.state, self.msg = "failed", "Host hat die Verbindung beendet"
                    netlog(f"Client: Host hat vor dem welcome geschlossen ({self.conn.error}, {self.conn.rx_bytes} B empfangen)")
                elif time.time() - self.t0 > 20.0:
                    self.state, self.msg = "failed", "Keine Antwort vom Host"
                    netlog(f"Client: kein welcome nach 20 s ({self.conn.rx_bytes} B empfangen)")
            if self.state in ("failed", "exp"):
                self.close()
        return self.state

    def close(self):
        if self.conn is not None:
            self.conn.close("abgebrochen")


class NetServer:
    """Nimmt TCP-Verbindungen an (Port NET_PORT). Wirft OSError, wenn der Port belegt ist."""

    def __init__(self, port=NET_PORT):
        self.lsock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            if os.name != "nt":      # unter Windows würde das Port-Klau erlauben
                self.lsock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.lsock.bind(("", port))
            self.lsock.listen(8)
            self.lsock.setblocking(False)
        except OSError:
            self.lsock.close()
            raise
        self.conns = []

    def accept(self):
        for _ in range(8):
            try:
                s, _addr = self.lsock.accept()
            except (BlockingIOError, InterruptedError):
                break
            except OSError:
                break
            netlog(f"Host: Verbindung angenommen von {_addr}")
            self.conns.append(Conn(s))

    def close(self):
        for c in self.conns:
            c.close("Host beendet")
        self.conns = []
        try:
            self.lsock.close()
        except OSError:
            pass


class Beacon:
    """Der Host ruft jede Sekunde per UDP-Broadcast 'hier läuft ein Spiel'."""

    def __init__(self, name, ip, port=NET_PORT, mode=""):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        self.sock.setblocking(False)
        self.name, self.port, self.mode = name, port, mode
        self.targets = [("255.255.255.255", DISCOVERY_PORT),
                        (ip.rsplit(".", 1)[0] + ".255", DISCOVERY_PORT)]   # typisches /24-WLAN
        self.t = 0.0

    def update(self, dt, nplayers):
        self.t -= dt
        if self.t > 0:
            return
        self.t = 1.0
        msg = json.dumps({"spiel": NET_VERSION, "name": self.name, "port": self.port,
                          "n": nplayers, "mode": self.mode}).encode()
        for tg in self.targets:
            try:
                self.sock.sendto(msg, tg)
            except OSError:
                pass

    def close(self):
        self.sock.close()


class Listener:
    """Hört im Menü auf die Broadcasts der Hosts. hosts: IP -> Infos."""

    def __init__(self):
        self.hosts = {}
        self.sock = None
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("", DISCOVERY_PORT))
            s.setblocking(False)
            self.sock = s
        except OSError:
            self.sock = None           # keine automatische Suche, IP eintippen geht trotzdem

    def poll(self):
        if self.sock is not None:
            for _ in range(32):
                try:
                    data, addr = self.sock.recvfrom(2048)
                except (BlockingIOError, InterruptedError):
                    break
                except OSError:
                    break
                try:
                    m = json.loads(data.decode())
                    if m.get("spiel") not in (NET_VERSION, EXP_NET_VERSION):
                        continue
                    exp = m.get("spiel") == EXP_NET_VERSION      # Host läuft in Experimental (Robins Version)
                    self.hosts[addr[0]] = dict(name=str(m.get("name", "?"))[:20],
                                               port=int(m.get("port", NET_PORT)),
                                               n=int(m.get("n", 1)), seen=time.time(), exp=exp,
                                               mode="experimental" if exp else str(m.get("mode", ""))[:8])
                except (ValueError, AttributeError, TypeError):
                    continue
        now = time.time()
        for ip in [ip for ip, h in self.hosts.items() if now - h["seen"] > 3.5]:
            del self.hosts[ip]
        return self.hosts

    def close(self):
        if self.sock is not None:
            self.sock.close()
            self.sock = None


class HostSession:
    """Host-Seite. Der Host ist selbst Spieler 0 und führt die Welt. Er nimmt
    Mitspieler an, übernimmt deren gemeldete Position/Schüsse und verschickt
    Snapshots. Position und Waffenzustand bleiben beim jeweiligen Spieler
    (kein Ruckeln); Monster, Kugeln, Schaden, Lebenspunkte, Punkte und
    Kistenwaffen entscheidet der Host."""

    def __init__(self, world, name):
        self.world = world
        self.server = NetServer()                 # kann OSError werfen (Port belegt)
        self.ip = local_ip()
        self.hama = hamachi_ip()
        self.ip_label = f"{self.hama} (Hamachi) oder {self.ip} (LAN)" if self.hama and self.hama != self.ip else self.ip
        self.last_poll = None
        self.last_phase = None
        netlog(f"Host: lauscht auf TCP {NET_PORT}; LAN-IP {self.ip}, Hamachi-IP {self.hama or '-'}, Modus {world.mode}")
        try:
            self.beacon = Beacon(name, self.ip, mode=world.mode)
        except OSError as e:
            netlog(f"Host: Host-Suche (UDP) nicht möglich: {e}")
            self.beacon = None
        self.next_pid = 1
        self.snap_t = 0.0
        self.events = []

    def close(self):
        self.server.close()
        if self.beacon is not None:
            self.beacon.close()

    def cfg_msg(self):
        w = self.world
        return {"t": "cfg", "mode": w.mode, "limit": w.limit, "mobs": 1 if w.mobs_on else 0,
                "tomahawk": 1 if w.tomahawk_on else 0, "cd": w.strike_cd, "regen": w.regen_rate}

    def send_cfg(self):
        """Neue Rundeneinstellungen an alle Mitspieler (gleiche Karte, keine Neuverbindung)."""
        m = self.cfg_msg()
        for c in self.server.conns:
            if c.pid is not None and not c.closed:
                c.send(m)
                c.flush()

    def rebind(self, world, info):
        """Kartenwechsel: neue Welt übernehmen, alle verbundenen Mitspieler bleiben (landen in der neuen Lobby)."""
        self.world = world
        self.events = []
        self.last_phase = None
        if self.beacon is not None:
            self.beacon.mode = world.mode
        for c in self.server.conns:
            if c.closed or c.pid is None:
                continue
            name, look = info.get(c.pid, (f"Spieler{c.pid}", ""))
            x, y = world.first_spawn(c.pid)
            pl = world.players[c.pid] = Player(x, y, world, c.pid, name)
            pl.look = look if look_valid(look) else ""
            pl.hp, pl.dead_age, pl.prespawn = 0.0, 1e9, True
            pl.ready = False
            c.playing = False                             # lädt jetzt die neue Karte
            c.pend_ev, c.stalled = [], False
            c.last_rx = time.time()
            c.send({"t": "reload", "id": c.pid, "seed": world.seed, "props": world.prop_count(),
                    "mode": world.mode, "limit": world.limit, "mobs": 1 if world.mobs_on else 0,
                    "tomahawk": 1 if world.tomahawk_on else 0, "map": getattr(world, "map_raw", None)})
            c.flush()
        netlog(f"Host: Welt gewechselt (Karte {'eigene' if getattr(world, 'map_raw', None) else 'Standard'}, "
               f"Modus {world.mode}), {len(world.players)} Spieler")

    def queue_events(self, events):
        """Ereignisse (Treffer, Tod, ...) für den nächsten Snapshot vormerken.
        'shot' nicht: den Rückstoss simuliert jeder Schütze selbst."""
        for e in events:
            if e[0] in ("matchend", "newmatch"):
                netlog(f"Host: Ereignis {e[0]} (Spieler {len(self.world.players)})")
        self.events.extend(e for e in events if e[0] != "shot")

    def refuse(self, c, why):
        netlog(f"Host: lehne Verbindung ab: {why}")
        c.send({"t": "refuse", "why": why})
        c.flush()
        c.close(why)

    def poll(self, dt):
        self.server.accept()
        now = time.time()
        if self.last_poll is not None and now - self.last_poll > 1.0:      # der Host selbst hing: Mitspieler hören nichts
            w = self.world
            netlog(f"Host: Frame-Hänger {now - self.last_poll:.1f}s (Phase {w.phase}, Spieler {len(w.players)}, "
                   f"Monster {len(w.mobs)}, Kugeln {len(w.bullets)})")
        self.last_poll = now
        for c in list(self.server.conns):
            if c.pid is not None and not getattr(c, "playing", False):
                lp = self.world.players.get(c.pid)
                if lp is not None:
                    lp.protect = PROTECT_T         # Beitretender lädt noch die Karte: so lange unverwundbar
            for m in c.recv():
                try:
                    self.handle(c, m)
                except (KeyError, IndexError, TypeError, ValueError):
                    pass                          # kaputte Nachricht ignorieren
                except Exception:
                    netlog_exc("Host.handle")     # nie den ganzen Host wegen einer Nachricht abstürzen lassen
            # Beitretende laden erst die Karte (bei Polytown mehrere Sekunden, ohne Daten zu senden): bis zur ersten
            # Positionsmeldung gilt eine lange Frist
            if not c.closed and now - c.last_rx > (NET_TIMEOUT if getattr(c, "playing", False) else NET_LOAD_TIMEOUT):
                c.close("Zeitüberschreitung")
            if c.closed:
                self.server.conns.remove(c)
                if c.pid is not None:
                    netlog(f"Host: Spieler pid {c.pid} entfernt ({c.error})")
                    gone = self.world.players.pop(c.pid, None)
                    self.world.clear_gadgets(c.pid)
                    if gone is not None:
                        self.world.drop_loot(gone)     # Kistenwaffe geht zurück in eine Kiste
            else:
                c.flush()

    def handle(self, c, m):
        if not isinstance(m, dict):
            return
        t, w = m.get("t"), self.world
        if t == "hello":
            if c.pid is not None:
                return
            netlog(f"Host: hello empfangen: Name {m.get('name')!r}, Version {m.get('v')} (Host {NET_VERSION})")
            if m.get("v") != NET_VERSION:
                return self.refuse(c, f"Andere Spielversion (Host: {VERSION})")
            if len(w.players) >= MAX_PLAYERS:
                return self.refuse(c, "Das Spiel ist voll")
            pid = self.next_pid
            self.next_pid += 1
            name = str(m.get("name") or f"Spieler{pid}")[:16]
            x, y = w.first_spawn(pid)
            w.players[pid] = Player(x, y, w, pid, name)
            lk = m.get("look")
            w.players[pid].look = lk if look_valid(lk) else ""
            npl = w.players[pid]
            npl.hp, npl.dead_age, npl.prespawn = 0.0, 1e9, True      # noch nicht gespawnt: wartet im Ausrüstungsbildschirm
            npl.ready = bool(w.phase == "over" and not w.lobby)       # im Rundenende beigetreten: kein Bereit nötig
            c.pid = pid
            netlog(f"Host: hello von '{name}' v{m.get('v')} -> pid {pid}, sende welcome")
            c.send({"t": "welcome", "id": pid, "seed": w.seed, "props": w.prop_count(),
                    "mode": w.mode, "limit": w.limit, "mobs": 1 if w.mobs_on else 0,
                    "tomahawk": 1 if w.tomahawk_on else 0,
                    "map": getattr(w, "map_raw", None)})
            return
        pl = w.players.get(c.pid)
        if pl is None:
            return
        if t == "st":                             # Position/Blickrichtung des Spielers
            if not getattr(c, "playing", False):
                netlog(f"Host: erste Position von pid {c.pid} - ab jetzt Snapshots")
            c.playing = True
            x, y, z, h, p = m["p"]
            if not finite(x, y, z, h, p):
                return
            pl.x, pl.y = clampf(x, -5, WORLD + 5), clampf(y, -5, WORLD + 5)
            pl.z = clampf(z, -20, 60)
            pl.heading, pl.pitch = h, clampf(p, -90, 90)
            pl.moving = bool(m.get("mv"))
            pl.running = bool(m.get("rn")) and pl.moving
            cur = m.get("cur")
            if isinstance(cur, int) and 0 <= cur < len(WEAPONS):
                pl.cur = cur
            ln = m.get("ln", 0.0)
            pl.lean = clampf(float(ln), -LEAN_MAX, LEAN_MAX) if finite(ln) else 0.0
            cr = m.get("cr", 0.0)
            pl.crouch = clampf(float(cr), 0.0, 1.0) if finite(cr) else 0.0
            gd_ = m.get("gd", -1)
            pl.hold_gad = gd_ if (isinstance(gd_, int) and -1 <= gd_ < len(GADGETS)) else -1
            pl.trig = bool(m.get("tg")) and (pl.mount >= 0 or pl.heli >= 0)
            pn_m = m.get("hc")                    # Pilot meldet seinen Helikopter
            if isinstance(pn_m, list) and len(pn_m) == 9 and finite(*pn_m):
                hc = w.heli_by_id(int(pn_m[0]))
                if hc is not None and hc.driver == pl.pid and hc.hp > 0:
                    hc.x, hc.y = clampf(pn_m[1], -5, WORLD + 5), clampf(pn_m[2], -5, WORLD + 5)
                    hc.z = clampf(pn_m[3], -5, HELI_CEIL + 20)
                    hc.heading, hc.pitch, hc.roll = pn_m[4], clampf(pn_m[5], -40, 40), clampf(pn_m[6], -60, 60)
                    hc.speed = clampf(pn_m[7], 0, HELI_VMAX * 1.5)
                    hc.ground = bool(pn_m[8])
            vh = m.get("vh")                      # Fahrer meldet sein Fahrzeug
            if isinstance(vh, list) and len(vh) == 6 and finite(*vh):
                v = w.vehicle_by_id(int(vh[0]))
                if v is not None and v.driver == pl.pid and v.hp > 0:
                    v.x, v.y = clampf(vh[1], -5, WORLD + 5), clampf(vh[2], -5, WORLD + 5)
                    v.z, v.heading = clampf(vh[3], -20, 60), vh[4]
                    v.speed = clampf(vh[5], -VEH_REV - 2, VEH_MAX + 2)
        elif t == "fire":                         # ein Schuss: Kugeln erzeugt der Host
            idx = m.get("w")
            if (pl.hp <= 0 or w.phase != "play" or not isinstance(idx, int)
                    or not 0 <= idx < len(WEAPONS)):
                return
            wp = eff_weapon(idx, m.get("a"))      # Schaden/Tempo kommen vom Host (Aufsätze werden geprüft)
            if wp.kind == "loot" and pl.loot != idx:
                return                            # Spezialwaffe nur, wenn aus einer Kiste erhalten
            dirs = []
            for d in (m.get("d") or [])[:wp.pellets]:
                if isinstance(d, list) and len(d) == 3 and finite(*d):
                    dirs.append(norm((float(d[0]), float(d[1]), float(d[2]))))
            if not dirs:
                return
            eye = (pl.x, pl.y, pl.z + eye_h(pl))
            o = m.get("o")
            if isinstance(o, list) and len(o) == 3 and finite(*o):
                if math.dist(o, eye) < 3.0:       # gemeldeter Mündungspunkt, wenn plausibel
                    eye = (float(o[0]), float(o[1]), float(o[2]))
            pl.cur = idx
            w.add_shot(pl, eye, dirs, wp)
        elif t == "gren":                         # Granate geworfen: der Host simuliert sie
            d, o = m.get("d"), m.get("o")
            if (pl.hp > 0 and pl.grenades > 0 and w.phase == "play" and pl.vehicle < 0
                    and isinstance(d, list) and len(d) == 3 and finite(*d)):
                eye = (pl.x, pl.y, pl.z + eye_h(pl))
                if isinstance(o, list) and len(o) == 3 and finite(*o) and math.dist(o, eye) < 3.0:
                    eye = (float(o[0]), float(o[1]), float(o[2]))
                pl.grenades -= 1
                pl.protect = 0.0
                w.spawn_grenade(pl.pid, eye, norm((float(d[0]), float(d[1]), float(d[2]))))
        elif t == "gad":                          # Gadget platzieren
            k, ps, nv = m.get("k"), m.get("p"), m.get("n")
            if (isinstance(k, int) and isinstance(ps, list) and len(ps) == 3 and finite(*ps)
                    and isinstance(nv, list) and len(nv) == 3 and finite(*nv)):
                eye = (pl.x, pl.y, pl.z + eye_h(pl))
                if math.dist(ps, eye) < GAD_RANGE + 3.0:
                    att = m.get("a")
                    att = (str(att[0]), int(att[1])) if (isinstance(att, list) and len(att) == 2
                                                         and att[0] in ("v", "h")) else None
                    yw = m.get("y", pl.heading)
                    w.place_gadget(pl, k, tuple(float(c) for c in ps), tuple(float(c) for c in nv),
                                   float(yw) if finite(yw) else pl.heading, att)
        elif t == "gdet":                         # C4 zünden
            w.detonate_c4(pl.pid)
        elif t == "use":                          # F (alt: V) gedrückt: Kiste, Waffe, Fahrzeug, Geschütz, Flugzeug
            w.use_object(pl, bool(m.get("alt")))
        elif t == "strikego":                     # Tomahawk mit gewähltem Einschlagpunkt abfeuern
            b = w.button
            if (finite(m.get("x", float("nan")), m.get("y", float("nan"))) and pl.hp > 0
                    and math.hypot(pl.x - b.x, pl.y - b.y) < 3.5 and abs(pl.z - b.z) < 2.5):
                w.press_button(pl, float(m["x"]), float(m["y"]))
        elif t == "hr":                           # Rakete aus dem Helikopter
            w.heli_rocket(pl)
        elif t == "melee":                        # Schlag mit der Waffe
            w.melee(pl)
        elif t == "fall":                         # Fallschaden, vom Mitspieler beim Aufprall gemeldet
            d = m.get("d")
            if finite(d) and pl.hp > 0 and pl.vehicle < 0 and pl.heli < 0:
                w.damage_player(pl, clampf(float(d), 0.0, PLAYER_HP * 2), -1, WI_FALL)
        elif t == "respawn":
            if w.can_respawn(pl):
                w.respawn_player(pl)              # Ereignis 'respawn' sagt dem Client, wohin
        elif t == "ready":                        # 'Bereit' in der Lobby / im Rundenendmenü
            if w.lobby or w.phase == "over":
                pl.ready = bool(m.get("v"))
        elif t == "rl":                           # Nachladen: die anderen sollen die Animation sehen
            idx = m.get("w")
            if pl.hp > 0 and isinstance(idx, int) and 0 <= idx < len(WEAPONS):
                w.events.append(("wreload", pl.pid, idx, 1))

    def send(self, dt):
        """Snapshot an alle Mitspieler (mit SNAP_RATE) und Host-Suche rufen."""
        w = self.world
        if w.phase != self.last_phase:
            if self.last_phase is not None:
                netlog(f"Host: Phase {self.last_phase} -> {w.phase}")
            self.last_phase = w.phase
        if self.beacon is not None:
            self.beacon.update(dt, len(w.players))
        # Snapshots erst, wenn der Beitretende die Karte geladen hat und seine erste Position meldet ("playing"):
        # sonst staut sich der Sendepuffer während des Ladens und der Host kappt ihn als "zu langsam"
        clients = [c for c in self.server.conns
                   if c.pid is not None and not c.closed and getattr(c, "playing", False)]
        self.snap_t -= dt
        if self.snap_t > 0:
            return
        self.snap_t = max(self.snap_t + 1.0 / SNAP_RATE, -1.0 / SNAP_RATE)     # gleichmässiger Takt statt Zeitverlust
        if not clients:
            self.events.clear()
            return
        self.snap_n = getattr(self, 'snap_n', 0) + 1
        snap = {"t": "snap", "rd": w.respawn_delay,
                "pl": [[p.pid, r2(-5.0 if p.prespawn else p.x), r2(-5.0 if p.prespawn else p.y), r2(-20.0 if p.prespawn else p.z), r1(p.heading), r1(p.pitch), r1(p.hp),
                        p.cur, 1 if p.moving else 0, p.name, p.kills, p.deaths, r1(p.score),
                        r1(p.protect), r2(p.lean), r2(p.crouch), p.look, 1 if p.ready else 0,
                        ((p.gadget if p.gad_out and p.hp > 0 else -1) if p.pid == 0 else p.hold_gad)]
                       for p in w.players.values()],
                "mb": [[m.id, KINDS.index(m.kind), r2(m.x), r2(m.y), r2(m.z), r1(m.heading),
                        STATES.index(m.state), r1(m.hp), r2(m.speed_now), r2(m.atk_t),
                        r2(m.hurt_t), r2(m.dead_t)] for m in w.mobs],
                "bl": [[b.bid, r2(b.x), r2(b.y), r2(b.z), r1(b.vx), r1(b.vy), r1(b.vz),
                        r1(b.travel), b.wi] for b in w.bullets],
                "cr": [c.content for c in w.crates],
                "gr": [[g.gid, r2(g.x), r2(g.y), r2(g.z), r1(g.vx), r1(g.vy), r1(g.vz), r1(g.fuse)]
                       for g in w.grenades],
                "dr": [[d.did, r2(d.x), r2(d.y), r2(d.z), d.wi] for d in w.drops],
                "gd": [[g.gid, g.kind, g.owner, r2(g.x), r2(g.y), r2(g.z), r2(g.nx), r2(g.ny), r2(g.nz), r1(g.yaw),
                        1 if g.arm > 0 else 0] for g in w.gadgets],
                "vh": [[v.id, r2(v.x), r2(v.y), r2(v.z), r1(v.heading), r1(v.speed), r1(v.hp),
                        v.driver, r1(v.dead_t)] for v in w.vehicles],
                "gm": [1 if w.phase == "over" else 0, r1(w.time_left), r1(w.over_t), 1 if w.lobby else 0],
                "tu": [[t.id, r1(t.heading), r1(t.pitch), r2(t.heat), 1 if t.over else 0,
                        1 if t.firing else 0, t.op] for t in w.turrets],
                "hc": [[q.id, r2(q.x), r2(q.y), r2(q.z), r1(q.heading), r1(q.pitch), r1(q.roll),
                        r1(q.speed), r1(q.hp), q.driver, r1(q.dead_t), int(q.mg), q.rk, 1 if q.ground else 0,
                        1 if q.firing else 0] for q in w.helis],
                "tm": [w.strike, r1(w.strike_t), w.strike_by, w.strike_dur, r1(w.strike_wait),
                       r1(w.strike_ang), r1(w.strike_x), r1(w.strike_y)],   # Ziel nur für den Anflug, nie angezeigt
                "k": w.kills, "ev": self.events}
        if self.snap_n % SB_EVERY == 1:                  # Scoreboard-Werte (Tab) - selten genügt
            snap["sb"] = [[p.pid] + list(stat_summary(p)) for p in w.players.values()]
        line = (json.dumps(snap, separators=(",", ":")) + "\n").encode()
        self.events = []
        ev_now = snap["ev"]
        for c in clients:
            if len(c.wbuf) > NET_STALE_BUF:           # Leitung staut: keine veralteten Snapshots anhäufen
                # einmalige Ereignisse (Rundenende, neue Runde, Treffer ...) gehen nicht verloren: sie warten auf den nächsten Snapshot
                c.pend_ev = (getattr(c, "pend_ev", []) + ev_now)[-300:]
                if not getattr(c, "stalled", False):
                    c.stalled = True
                    netlog(f"Host: Leitung zu pid {c.pid} staut ({len(c.wbuf)} B ungesendet) - Snapshots ausgelassen")
                c.flush()
                continue
            if getattr(c, "stalled", False) and len(c.wbuf) < 4000:
                c.stalled = False
                netlog(f"Host: Leitung zu pid {c.pid} frei, Snapshots laufen wieder")
            pend = getattr(c, "pend_ev", None)
            if pend:                                  # nach einem Stau: aufgesparte Ereignisse nachliefern
                snap2 = dict(snap)
                snap2["ev"] = pend + ev_now
                c.send_line((json.dumps(snap2, separators=(",", ":")) + "\n").encode())
                c.pend_ev = []
            else:
                c.send_line(line)
            c.flush()
        if self.snap_n % 150 == 1 and clients:       # alle ~5 s: Zustand jeder Leitung
            netlog("Host: Snapshot " + str(len(line)) + " B; je Spieler (pid, ungesendet B, gesendet gesamt B, stumm s): " +
                   str([(c.pid, len(c.wbuf), c.tx_bytes, round(time.time() - c.last_rx, 1)) for c in clients]))


class NetMob:
    """Monster-Stellvertreter beim Mitspieler: wird aus den Snapshots gefüttert und
    gleitet weich auf die gemeldete Position. Hat die Felder, die MobView braucht."""

    def __init__(self, mid, kind, x, y, z, heading):
        k = MOB_KINDS[kind]
        self.id, self.kind = mid, kind
        self.scale = k["scale"]
        self.radius = 0.45 * self.scale
        self.max_hp = self.hp = k["hp"]
        self.x = self.tx = x
        self.y = self.ty = y
        self.z = self.tz = z
        self.heading = self.th = heading
        self.height = 1.9 * self.scale
        self.state = "idle"
        self.atk_t = self.dead_t = self.hurt_t = self.speed_now = self.phase = 0.0

    def apply(self, x, y, z, heading, state, hp, speed, atk, hurt, dead):
        self.tx, self.ty, self.tz, self.th = x, y, z, heading
        if state != self.state:
            self.state, self.atk_t, self.dead_t = state, atk, dead
        else:                                      # sonst läuft die Zeit lokal weiter
            if abs(atk - self.atk_t) > 0.15:
                self.atk_t = atk
            if abs(dead - self.dead_t) > 0.3:
                self.dead_t = dead
        self.hp, self.speed_now = hp, speed
        self.hurt_t = max(self.hurt_t, hurt)

    def smooth(self, dt):
        a = min(1.0, 16.0 * dt)
        self.x += (self.tx - self.x) * a
        self.y += (self.ty - self.y) * a
        self.z += (self.tz - self.z) * a
        self.heading += ((self.th - self.heading + 180.0) % 360.0 - 180.0) * a
        if self.state == "attack":
            self.atk_t += dt
        elif self.state == "dead":
            self.dead_t += dt
        self.hurt_t = max(0.0, self.hurt_t - dt)
        self.phase += self.speed_now * dt * 2.0


class ClientSession:
    """Mitspieler-Seite: schickt eigene Position/Schüsse zum Host und baut aus den
    Snapshots Monster, Kugeln, Kisten, Punkte und die anderen Spieler in der lokalen World auf."""

    def __init__(self, conn, world, my_id, backlog=()):
        self.conn, self.world, self.my_id = conn, world, my_id
        self.mobs = {}               # Monster-ID -> NetMob
        self.bullets = {}            # Kugel-ID -> Bullet (nur zum Anzeigen)
        self.grenades = {}           # Granaten-ID -> Grenade (nur zum Anzeigen)
        self.gadgets = {}            # Gadget-ID -> Gadget (nur zum Anzeigen)
        self.drops = {}              # Drop-ID -> Drop (fallengelassene Waffen)
        self.events = []             # vom Host gemeldete Ereignisse
        self.hp = None               # Lebenspunkte: entscheidet der Host
        self.lost = ""               # Text, wenn die Verbindung weg ist
        self.send_t = 0.0
        self.fresh = True            # erster Frame nach dem Kartenbau: Zeitmessung "Host schweigt" beginnt erst dann
        self.got_snap = False
        self.stall_t0 = time.time()
        self.n_snap, self.max_gap = 0, 0.0
        self.last_msg_t = self.sum_t = time.time()
        self.reload = None           # Host wechselt die Karte: Daten für den Neuaufbau
        self.cfg_changed = False     # Host hat die Rundeneinstellungen geändert
        netlog(f"Client: Sitzung angelegt (id {my_id}), {len(list(backlog))} Nachrichten im Rückstau")
        for m in backlog:
            self.handle(m)

    def close(self):
        self.conn.close("beendet")

    def poll(self, dt):
        if self.lost:
            return
        if self.fresh:
            self.fresh = False
            self.conn.last_rx = self.last_msg_t = self.sum_t = time.time()
            netlog("Client: Karte fertig, erster Frame - sende Positionen")
        now = time.time()
        self.max_dt = max(getattr(self, "max_dt", 0.0), dt)
        gap = now - self.conn.last_rx
        if gap > 2.0 and not getattr(self, "stall_log", False):
            self.stall_log = True
            netlog(f"Client: Daten vom Host stocken seit {gap:.1f}s (größter Frame-dt {self.max_dt:.2f}s)")
        msgs = self.conn.recv()
        if msgs and getattr(self, "stall_log", False):
            self.stall_log = False
            netlog(f"Client: Daten wieder da nach {now - self.stall_t0:.1f}s")
        if not getattr(self, "stall_log", False):
            self.stall_t0 = now
            self.max_dt = 0.0
        if msgs:
            self.max_gap = max(self.max_gap, now - self.last_msg_t)
            self.last_msg_t = now
        for m in msgs:
            self.handle(m)
        if now - self.sum_t >= 5.0:                  # alle 5 s ein Lebenszeichen mit der längsten Pause
            netlog(f"Client: letzte 5 s: {self.n_snap} Snapshots, längste Pause {self.max_gap:.2f}s, "
                   f"{self.conn.rx_bytes} B empfangen gesamt")
            self.sum_t, self.n_snap, self.max_gap = now, 0, 0.0
        if not self.conn.closed and time.time() - self.conn.last_rx > NET_TIMEOUT:
            netlog(f"Client: {NET_TIMEOUT:.0f}s keine Daten vom Host (Snapshot je erhalten: {self.got_snap})")
            self.conn.close("Zeitüberschreitung")
        if self.conn.closed:
            self.lost = self.conn.error or "Verbindung getrennt"
        else:
            self.conn.flush()

    def handle(self, m):
        if not isinstance(m, dict):
            return
        try:
            if m.get("t") == "snap":
                if not self.got_snap:
                    self.got_snap = True
                    netlog("Client: erster Snapshot vom Host empfangen")
                self.n_snap += 1
                self.apply_snapshot(m)
            elif m.get("t") == "cfg":
                w = self.world
                if m.get("mode") in MODES and not w.mc:
                    w.mode = m["mode"]
                w.limit = clampf(float(m.get("limit", w.limit)), 30.0, 7200.0)
                w.mobs_on = bool(m.get("mobs", w.mobs_on))
                w.tomahawk_on = bool(m.get("tomahawk", w.tomahawk_on))
                w.strike_cd = float(m.get("cd", w.strike_cd))
                w.regen_rate = float(m.get("regen", w.regen_rate))
                self.cfg_changed = True
            elif m.get("t") == "reload":
                self.reload = m
        except (KeyError, IndexError, TypeError, ValueError):
            pass
        except Exception:
            netlog_exc("Client.handle")               # nie den ganzen Client wegen einer Nachricht abstürzen lassen

    def apply_snapshot(self, m):
        w = self.world
        try:
            w.respawn_delay = float(m.get("rd", w.respawn_delay))
        except (TypeError, ValueError):
            pass
        seen = set()
        for row in m["pl"]:
            pid, x, y, z, h, p, hp, cur, mv, name, kl, de, sc, prot, ln, cr = row[:16]
            lk = row[16] if len(row) > 16 else ""
            rdy = bool(row[17]) if len(row) > 17 else False
            hg = row[18] if len(row) > 18 else -1
            if pid == self.my_id:
                self.hp = hp                       # Position bestimmt der Spieler selbst
                me = w.players.get(pid)
                if me is not None:
                    me.kills, me.deaths, me.score, me.protect = kl, de, sc, prot
                    if time.time() - me.ready_set > 0.7:
                        me.ready = rdy             # der Host bestimmt (z.B. Zurücksetzen bei Rundenstart)
                continue
            pl = w.players.get(pid)
            if pl is None:
                pl = w.players[pid] = Player(x, y, w, pid, str(name))
            pl.x, pl.y, pl.z, pl.heading, pl.pitch = x, y, z, h, p
            pl.hp, pl.cur, pl.moving, pl.lean = hp, cur, bool(mv), ln
            pl.crouch = cr
            pl.look = lk if look_valid(lk) else ""
            pl.kills, pl.deaths, pl.score, pl.protect = kl, de, sc, prot
            pl.ready, pl.hold_gad = rdy, (hg if isinstance(hg, int) else -1)
            seen.add(pid)
        for pid in [pid for pid in w.players if pid != self.my_id and pid not in seen]:
            del w.players[pid]
        for row in m.get("sb", ()):                      # Tab-Scoreboard: Monster, Kisten
            q = w.players.get(row[0])
            if q is not None and len(row) >= 3:
                q.sb = tuple(int(v) for v in row[1:3])

        seen = set()
        for mid, ki, x, y, z, hd, si, hp, spd, atk, hurt, dead in m["mb"]:
            nm = self.mobs.get(mid)
            if nm is None:
                nm = self.mobs[mid] = NetMob(mid, KINDS[ki], x, y, z, hd)
            nm.apply(x, y, z, hd, STATES[si], hp, spd, atk, hurt, dead)
            seen.add(mid)
        for mid in [i for i in self.mobs if i not in seen]:
            del self.mobs[mid]
        w.mobs = list(self.mobs.values())

        seen = set()
        for bid, x, y, z, vx, vy, vz, tr, wi in m["bl"]:
            b = self.bullets.get(bid)
            if b is None:
                b = self.bullets[bid] = Bullet(x, y, z, vx, vy, vz, 0.0, 0, bid, wi)
            b.x, b.y, b.z, b.vx, b.vy, b.vz, b.travel = x, y, z, vx, vy, vz, tr
            seen.add(bid)
        for bid in [i for i in self.bullets if i not in seen]:
            del self.bullets[bid]
        w.bullets = list(self.bullets.values())

        for c, v in zip(w.crates, m.get("cr", ())):
            c.content = v

        seen = set()
        for gid, x, y, z, vx, vy, vz, fuse in m.get("gr", ()):
            g = self.grenades.get(gid)
            if g is None:
                g = self.grenades[gid] = Grenade(gid, x, y, z, vx, vy, vz, -1, fuse)
            g.x, g.y, g.z, g.vx, g.vy, g.vz, g.fuse = x, y, z, vx, vy, vz, fuse
            seen.add(gid)
        for gid in [i for i in self.grenades if i not in seen]:
            del self.grenades[gid]
        w.grenades = list(self.grenades.values())

        seen = set()
        for gid, kd, ow, x, y, z, nx, ny, nz, yw, ar in m.get("gd", ()):
            g = self.gadgets.get(gid)
            if g is None:
                g = self.gadgets[gid] = Gadget(gid, kd, ow, x, y, z, nx, ny, nz, yw)
            g.x, g.y, g.z, g.nx, g.ny, g.nz = x, y, z, nx, ny, nz
            g.arm = 1.0 if ar else 0.0
            seen.add(gid)
        for gid in [i for i in self.gadgets if i not in seen]:
            del self.gadgets[gid]
        w.gadgets = list(self.gadgets.values())

        seen = set()
        for did, x, y, z, wi in m.get("dr", ()):
            d = self.drops.get(did)
            if d is None:
                d = self.drops[did] = Drop(did, x, y, z, wi)
            seen.add(did)
        for did in [i for i in self.drops if i not in seen]:
            del self.drops[did]
        w.drops = list(self.drops.values())

        for vid, x, y, z, hd, sp, hp, drv, dead in m.get("vh", ()):
            v = w.vehicle_by_id(vid)
            if v is None:
                continue
            v.hp, v.driver, v.dead_t = hp, drv, dead
            if drv != self.my_id:                  # den eigenen Wagen bestimmt der Fahrer selbst
                v.x, v.y, v.z, v.heading, v.speed = x, y, z, hd, sp
        taken = {v.driver: v.id for v in w.vehicles if v.driver >= 0}
        for pid, pl in w.players.items():          # wer sitzt in welchem Fahrzeug?
            pl.vehicle = taken.get(pid, -1)
        ops = {}
        for tid, hd, pt, heat, over, fr, op in m.get("tu", ()):
            if 0 <= tid < len(w.turrets):
                t = w.turrets[tid]
                t.heat, t.over, t.firing, t.op = heat, bool(over), bool(fr), op
                if op != self.my_id:                 # den eigenen Zielwinkel bestimmt der Schütze selbst
                    t.heading, t.pitch = hd, pt
                if op >= 0:
                    ops[op] = tid
        for pid, pl in w.players.items():
            pl.mount = ops.get(pid, -1)
        for qid, x, y, z, hd, pt, rl, sp, hp, drv, dd, mg, rk, gr, fr in m.get("hc", ()):
            q = w.heli_by_id(qid)
            if q is None:
                continue
            q.hp, q.driver, q.dead_t, q.mg, q.rk, q.firing = hp, drv, dd, mg, rk, bool(fr)
            if drv != self.my_id:                    # den eigenen Helikopter bestimmt der Pilot selbst
                q.x, q.y, q.z, q.heading, q.pitch, q.roll, q.speed, q.ground = x, y, z, hd, pt, rl, sp, bool(gr)
        pil = {q.driver: q.id for q in w.helis if q.driver >= 0}
        for pid, pl in w.players.items():
            pl.heli = pil.get(pid, -1)
        tm = m.get("tm")
        if tm:
            w.strike, w.strike_t, w.strike_by = tm[0], tm[1], tm[2]
            if len(tm) > 3:
                w.strike_dur = tm[3]
            if len(tm) > 4:
                w.strike_wait = tm[4]
            if len(tm) > 7:
                w.strike_ang, w.strike_x, w.strike_y = tm[5], tm[6], tm[7]
        gm = m.get("gm")
        if gm:
            w.phase = "over" if gm[0] else "play"
            w.time_left, w.over_t = gm[1], gm[2]
            if len(gm) > 3:
                w.lobby = bool(gm[3])
        w.kills = m.get("k", w.kills)
        for e in m.get("ev", ()):
            self.events.append(tuple(e))

    def advance(self, dt):
        """Zwischen zwei Snapshots weiterrechnen: Kugeln fliegen (nur zur Anzeige),
        Monster gleiten weich."""
        for b in self.bullets.values():
            b.vz -= GRAV_BULLET * b.grav * dt
            b.x += b.vx * dt
            b.y += b.vy * dt
            b.z += b.vz * dt
            b.travel += math.sqrt(b.vx ** 2 + b.vy ** 2 + b.vz ** 2) * dt
        for nm in self.mobs.values():
            nm.smooth(dt)
        w = self.world
        for g in self.grenades.values():           # zwischen zwei Snapshots weiterfliegen
            g.vz -= GREN_G * dt
            g.x += g.vx * dt
            g.y += g.vy * dt
            g.z = max(g.z + g.vz * dt, w.ground_for(g.x, g.y, g.z) + 0.1)
            g.fuse -= dt
        if w.strike == 1:
            w.strike_t = max(0.0, w.strike_t - dt)
        elif w.strike == 2 and w.strike_wait > 0:
            w.strike_wait = max(0.0, w.strike_wait - dt)
        w.sync_turret_pos()

    def send_state(self, dt, pl):
        self.send_t -= dt
        if self.send_t > 0:
            return
        self.send_t = max(self.send_t + 1.0 / INPUT_RATE, -1.0 / INPUT_RATE)
        msg = {"t": "st", "p": [r2(pl.x), r2(pl.y), r2(pl.z), r1(pl.heading), r1(pl.pitch)],
               "mv": 1 if pl.moving else 0, "cur": pl.cur, "ln": r2(pl.lean),
               "cr": r2(pl.crouch), "rn": 1 if getattr(pl, "running", False) else 0,
               "gd": pl.gadget if (pl.gad_out and pl.hp > 0) else -1}
        v = self.world.vehicle_by_id(pl.vehicle) if pl.vehicle >= 0 else None
        if v is not None:
            msg["vh"] = [v.id, r2(v.x), r2(v.y), r2(v.z), r1(v.heading), r1(v.speed)]
        if pl.mount >= 0 or pl.heli >= 0:
            msg["tg"] = 1 if pl.trig else 0
        q = self.world.heli_by_id(pl.heli) if pl.heli >= 0 else None
        if q is not None:
            msg["hc"] = [q.id, r2(q.x), r2(q.y), r2(q.z), r1(q.heading), r1(q.pitch), r1(q.roll),
                         r1(q.speed), 1 if q.ground else 0]
        self.conn.send(msg)

    def send_grenade(self, pl, eye, d):
        """World.gren_sink: den Wurf dem Host melden (er simuliert die Granate)."""
        self.conn.send({"t": "gren", "o": [r2(c) for c in eye], "d": [round(c, 4) for c in d]})
        self.conn.flush()

    def send_gadget(self, what, pl, kind, pos, nrm, yaw, att):
        """World.gad_sink: Gadget platzieren / C4 zünden dem Host melden."""
        if what == "det":
            self.conn.send({"t": "gdet"})
        else:
            self.conn.send({"t": "gad", "k": kind, "p": [r2(c) for c in pos], "n": [r2(c) for c in nrm],
                            "y": r1(yaw), "a": list(att) if att else None})
        self.conn.flush()

    def send_shot(self, pl, eye, dirs, w):
        """World.shot_sink: den Schuss dem Host melden (er erzeugt die Kugeln)."""
        msg = {"t": "fire", "w": pl.cur, "o": [r2(v) for v in eye],
               "d": [[round(v, 4) for v in d] for d in dirs]}
        a = pl.att.get(pl.cur)
        if a:
            msg["a"] = list(a)
        self.conn.send(msg)
        self.conn.flush()

    def send_strike(self, x, y):
        self.conn.send({"t": "strikego", "x": round(float(x), 1), "y": round(float(y), 1)})
        self.conn.flush()

    def send_melee(self):
        self.conn.send({"t": "melee"})

    def send_use(self, alt=False):
        self.conn.send({"t": "use", "alt": 1} if alt else {"t": "use"})

    def send_rocket(self):
        self.conn.send({"t": "hr"})
        self.conn.flush()

    def send_fall(self, dmg):
        """Fallschaden melden (die eigene Figur bewegt der Mitspieler selbst, Schaden rechnet der Host)."""
        self.conn.send({"t": "fall", "d": round(float(dmg), 1)})
        self.conn.flush()

    def request_respawn(self):
        self.conn.send({"t": "respawn"})

    def send_ready(self, v):
        self.conn.send({"t": "ready", "v": 1 if v else 0})
        self.conn.flush()

    def send_reload(self, wi):
        self.conn.send({"t": "rl", "w": int(wi)})


def melee_curve(u):
    """Schlag-Verlauf 0..1 -> (Ausholen, Zuschlagen): Ausholen 0..1 bis u=0.35, dann Schlag nach vorn, Rückkehr."""
    wind = smoothstep(0.0, 0.35, u) * (1.0 - smoothstep(0.35, 0.55, u))
    hit = smoothstep(0.33, 0.52, u) * (1.0 - smoothstep(0.55, 1.0, u))
    return wind, hit


def melee_pitch(u):
    wind, hit = melee_curve(u)
    return 55.0 * wind - 60.0 * hit


def kf_pos(kf, u):
    """Hand-Zielposition zwischen Schlüsselpunkten ((u, (x, y, z)), ...) mit weichen Übergängen."""
    for i in range(len(kf) - 1):
        if u <= kf[i + 1][0]:
            t = smoothstep(kf[i][0], kf[i + 1][0], u)
            return _lerp3(kf[i][1], kf[i + 1][1], t)
    return kf[-1][1]


def aim_arm(node, v0, tgt):
    """Dreht einen Arm um die Schulter (Ursprung des Knotens) so, dass der Vektor zur Hand von v0 nach tgt zeigt
    (kleinste Drehung, Armlänge bleibt gleich). So lassen sich Hände einfach an Zielpunkte führen."""
    a, b = norm(v0), norm(tgt)
    c = clampf(dot(a, b), -1.0, 1.0)
    ax = cross(a, b)
    if dot(ax, ax) < 1e-9:
        if c > 0:
            node.setQuat(Quat.identQuat())
            return
        ax = (1.0, 0.0, 0.0)
    q = Quat()
    q.setFromAxisAngle(math.degrees(math.acos(c)), Vec3(*norm(ax)))
    node.setQuat(q)


def rot_x(v, deg):
    c, sn = math.cos(math.radians(deg)), math.sin(math.radians(deg))
    return (v[0], v[1] * c - v[2] * sn, v[1] * sn + v[2] * c)


# Hand-Zielpunkte (Torso-Raum) der Soldaten-Animationen
_MAG_SLOT = (0.10, 0.30, 0.27)           # Magazinschacht unter der Waffe
SOLDIER_RELOAD_L = ((0.00, SOLDIER_HAND[0]), (0.18, _MAG_SLOT), (0.38, (0.08, 0.28, 0.10)), (0.58, (0.0, 0.20, 0.36)),
                    (0.66, (0.0, 0.20, 0.36)), (0.88, _MAG_SLOT), (1.00, SOLDIER_HAND[0]))   # Magazin raus, aus der Weste, rein
SOLDIER_THROW_R = ((0.00, SOLDIER_HAND[1]), (0.15, (0.32, -0.30, 0.80)), (0.32, (0.20, 0.45, 0.75)),
                   (0.48, (0.15, 0.30, 0.12)), (1.00, SOLDIER_HAND[1]))                      # ausholen, werfen, ausschwingen
SOLDIER_THROW_L = ((0.00, SOLDIER_HAND[0]), (0.20, (-0.30, 0.10, 0.28)), (0.80, (-0.30, 0.10, 0.28)),
                   (1.00, SOLDIER_HAND[0]))                                                  # linker Arm schwingt locker mit


# Gehaltene Waffe der Mitspieler: (Massstab, rechter Griff (y, z), linke Hand (y, z)) im Waffenraum. Die rechte Hand
# sitzt immer am Griff (SOLDIER_HAND[1]), die linke am Handschutz bzw. unter dem Griff.
HELD_GUN = {"Pistole": (0.90, (0.0, -0.05), (0.02, -0.12)), "Revolver": (0.90, (-0.03, -0.05), (-0.02, -0.12)),
            "Maschinenpistole": (0.80, (-0.02, -0.05), (0.08, -0.10)), "Sturmgewehr": (0.68, (0.06, -0.09), (0.42, -0.035)),
            "Schrotflinte": (0.62, (-0.03, -0.04), (0.35, -0.065)), "Scharfschütze": (0.56, (-0.09, -0.07), (0.35, -0.04)),
            "Raketenwerfer": (0.50, (0.10, -0.10), (0.36, -0.10)), "Minigun": (0.50, (0.0, -0.12), (0.05, 0.12)),
            "Railgun": (0.62, (0.05, -0.10), (0.35, 0.0))}
_HELD_CACHE = {}


def held_gun_geom(wi):
    """Detailliertes Waffenmodell für die Ansicht von aussen (ein GeomNode je Waffe, von allen Figuren geteilt)."""
    g = _HELD_CACHE.get(wi)
    if g is None:
        w = WEAPONS[wi]
        sh = GUN_SHAPES[w.name]
        m = Mesh()
        rng = random.Random(11 + wi)
        build_shapes(m, sh["body"] + sh["barrel"] + sh["iron"], rng)
        mp = MAG_PARTS.get(w.name)
        if mp is not None:
            build_shapes(m, sh["mag"], rng, (mp[0], mp[1], mp[2]))
        g = _HELD_CACHE[wi] = m.node("held_" + w.name)
    return g


def held_hands(name):
    """(Massstab, Ruheposition der linken Hand im Torso-Raum) für die gehaltene Waffe."""
    s_, rg, lg = HELD_GUN[name]
    hr = SOLDIER_HAND[1]
    return s_, (hr[0], hr[1] + s_ * (lg[0] - rg[0]), hr[2] + s_ * (lg[1] - rg[1]))


_FLASH_GEOM = None


def flash_geom():
    """Mündungsfeuer als Stern (ein GeomNode, von allen Figuren geteilt)."""
    global _FLASH_GEOM
    if _FLASH_GEOM is None:
        m = Mesh(lit=False)
        pts = []
        for i in range(8):
            a = 2 * math.pi * i / 8
            rr = 0.11 if i % 2 == 0 else 0.045
            pts.append((math.cos(a) * rr, 0.0, math.sin(a) * rr))
        for i in range(8):
            m.tri((0, 0, 0), pts[i], pts[(i + 1) % 8], (1.0, 0.85, 0.4))
        _FLASH_GEOM = m.node("flash")
    return _FLASH_GEOM


class PlayerView:
    """Darstellung eines Mitspielers: Figur mit Waffe (ohne Namensschild und Lebensbalken)."""

    def __init__(self, p):
        look = soldier_look(getattr(p, "look", ""), p.pid)
        (self.root, self.torso, self.legL, self.legR, self.bar, self.fg,
         self.armL, self.armR) = build_soldier(look)
        gc = (0.13, 0.13, 0.15)
        sr = SOLDIER_SH[1]
        self.gun = self.armR.attachNewNode("gun")                         # Halter am rechten Arm; darin die gehaltene Waffe
        self.gun.setPos(-sr[0], -sr[1], -sr[2])
        self.held, self.held_cur = {}, -1
        self.flash, self.flash_t, self.kick = {}, 0.0, 0.0                 # Mündungsfeuer und Rückstoss der anderen
        self.gadn, self.gad_cur = {}, -1                                   # Gadget in der Hand (je Art ein Modell)
        self.src, self.src_t, self.vel = None, 0.0, (0.0, 0.0)             # Empfangsposition / Geschwindigkeit (Vorausberechnung)
        self.hl = SOLDIER_HAND[0]                                         # Ruheposition der linken Hand (je Waffe)
        mm = Mesh()
        box(mm, 0, 0.0, -0.03, 0.04, 0.07, 0.12, gc)                       # Magazin in der linken Hand
        self.mag_nd = self.armL.attachNewNode(mm.node("hand_mag"))
        hl = sub(SOLDIER_HAND[0], SOLDIER_SH[0])
        self.mag_nd.setPos(*hl)
        self.mag_nd.hide()
        gr = Mesh()
        blob(gr, 0, 0, 0.0, 0.040, 0.040, 0.052, (0.22, 0.30, 0.16), random.Random(4), jitter=0.04)   # Handgranate
        box(gr, 0, 0, 0.055, 0.022, 0.022, 0.02, (0.6, 0.6, 0.55))
        self.gren_nd = self.armR.attachNewNode(gr.node("hand_gren"))
        self.gren_nd.setPos(*sub(SOLDIER_HAND[1], sr))
        self.gren_nd.setZ(self.gren_nd.getZ() + 0.03)
        self.gren_nd.hide()
        self.slung = False
        self.swing = 0.0
        self.rl_t = self.rl_tot = 0.0                                 # Nachladen (von "wreload"): Restzeit / Gesamtdauer
        self.rl_sg = False
        self.th_t = 0.0                                               # Granatwurf (von "throw")
        self.bar.hide()                                               # keine Lebensbalken über Mitspielern
        # (und auch keine Namensschilder)
        self.x, self.y, self.z, self.h = p.x, p.y, p.z, p.heading
        self.phase = 0.0
        self.dead_t = 0.0

    def show_held(self, wi):
        """Die Waffe in der Hand wechseln (Modell je Waffe einmal pro Figur angehängt)."""
        if wi == self.held_cur or not (0 <= wi < len(WEAPONS)):
            return
        self.held_cur = wi
        name = WEAPONS[wi].name
        if wi not in self.held:
            s_, rg, _lg = HELD_GUN[name]
            hr = SOLDIER_HAND[1]
            nd = self.gun.attachNewNode(held_gun_geom(wi))
            nd.setScale(s_)
            nd.setPos(hr[0], hr[1] - s_ * rg[0], hr[2] - s_ * rg[1])
            self.held[wi] = nd
            fl = nd.attachNewNode("mflash")                               # Mündungsfeuer: zwei gekreuzte Sterne am Laufende
            for hh in (0, 90):
                fl.attachNewNode(flash_geom()).setH(hh)
            fl.setPos(*GUN_PARTS[name][1])
            fl.setScale(2.2)
            fl.setTwoSided(True)
            fl.setLightOff()
            fl.hide()
            self.flash[wi] = fl
        for k, nd in self.held.items():
            (nd.show if k == wi else nd.hide)()
        self.hl = held_hands(name)[1]

    def fire(self, wi):
        """Ein Schuss dieses Spielers: Mündungsfeuer blitzt kurz auf, die Waffe schlägt zurück."""
        if not (0 <= wi < len(WEAPONS)):
            return
        self.show_held(wi)
        fl = self.flash.get(wi)
        if fl is not None:
            fl.setR(random.uniform(0, 360))
            fl.setScale(random.uniform(1.7, 2.6) * (1.5 if WEAPONS[wi].pellets > 1 else 1.0))
        self.flash_t = 0.06
        self.kick = 1.0

    def show_gadget(self, k):
        """Gadget (C4, Claymore, Funkbake) statt der Waffe in der Hand zeigen; k = -1: Waffe."""
        if k == self.gad_cur:
            return
        self.gad_cur = k
        if k >= 0 and k not in self.gadn:
            hr = SOLDIER_HAND[1]
            nd = self.gun.attachNewNode(gadget_mesh(k).node("hand_gadget%d" % k))
            nd.setPos(hr[0], hr[1] + 0.06, hr[2] - 0.02)
            nd.setScale(1.2)
            self.gadn[k] = nd
        for kk, nd in self.gadn.items():
            (nd.show if kk == k else nd.hide)()

    def start_reload(self, wi):
        if not (0 <= wi < len(WEAPONS)) or self.th_t > 0:
            return
        w = WEAPONS[wi]
        self.rl_sg = w.name == SG_NAME
        self.rl_tot = sg_times(5)[1] if self.rl_sg else max(0.5, w.reload)
        self.rl_t = self.rl_tot

    def start_throw(self):
        self.th_t = GREN_ANIM_T
        self.rl_t = 0.0

    def pose_arms(self, dt):
        """Arme: beide Hände an der Waffe; Nachladen (linke Hand holt das Magazin aus der Weste), Granatwurf
        (rechter Arm holt aus, Waffe hängt am Gurt) und Schlag (Waffe mit beiden Armen)."""
        SL, SR = SOLDIER_SH
        HL, HR = self.hl, SOLDIER_HAND[1]
        v0L, v0R = sub(HL, SL), sub(HR, SR)
        tl, tr = HL, HR
        tilt = 0.0
        mag = gren = slung = False
        py = 0.0
        if self.th_t > 0:
            self.th_t = max(0.0, self.th_t - dt)
            u = 1.0 - self.th_t / GREN_ANIM_T
            tl, tr = kf_pos(SOLDIER_THROW_L, u), kf_pos(SOLDIER_THROW_R, u)
            slung = True
            gren = u < 0.33                                           # loslassen beim Vorschwung
        elif self.rl_t > 0:
            self.rl_t = max(0.0, self.rl_t - dt)
            tt = self.rl_tot - self.rl_t
            u = tt / self.rl_tot
            tilt = 8.0 * smoothstep(0.0, 0.15, u) * (1.0 - smoothstep(0.85, 1.0, u))
            if self.rl_sg:                                            # Patronen: Hand pendelt zwischen Weste und Lauf
                k = 0.5 - 0.5 * math.cos(2 * math.pi * tt / 0.6)
                tl = _lerp3((0.0, 0.20, 0.36), _MAG_SLOT, k)
                tilt = 12.0 * smoothstep(0.0, 0.2, u) * (1.0 - smoothstep(0.85, 1.0, u))
            else:
                tl = kf_pos(SOLDIER_RELOAD_L, u)
                away = smoothstep(0.0, 0.18, u) * (1.0 - smoothstep(0.88, 1.0, u))      # Ruheposition je Waffe vorn/hinten
                tl = add(tl, tuple(c * (1.0 - away) for c in sub(HL, SOLDIER_HAND[0])))
                mag = (0.18 <= u < 0.38) or (0.58 <= u < 0.88)        # altes Magazin raus, neues in der Hand
        elif self.swing > 0:                                          # Schlag: Waffe hoch, dann nach unten
            self.swing = max(0.0, self.swing - dt)
            u = 1.0 - self.swing / MELEE_T
            pm = melee_pitch(u) * 0.9
            tr = add(SR, rot_x(v0R, pm))
            tl = add(SL, rot_x(v0L, pm * 0.6))
            py = 0.15 * math.sin(math.pi * u)
        if tilt:
            tr = add(SR, rot_x(v0R, tilt))
        if slung != self.slung:                                       # Waffe beim Wurf am Gurt vor dem Körper
            self.slung = slung
            if slung:
                self.gun.reparentTo(self.torso)
                self.gun.setPos(0, 0, -0.10)
                self.gun.setP(-35)
            else:
                self.gun.reparentTo(self.armR)
                self.gun.setPos(-SR[0], -SR[1], -SR[2])
                self.gun.setP(0)
        (self.mag_nd.show if mag else self.mag_nd.hide)()
        (self.gren_nd.show if gren else self.gren_nd.hide)()
        self.armR.setPos(SR[0], SR[1] + py, SR[2])
        aim_arm(self.armR, v0R, sub(tr, SR))
        aim_arm(self.armL, v0L, sub(tl, SL))

    def update(self, p, dt):
        if math.hypot(p.x - self.x, p.y - self.y) > 8.0:                 # Sprung (Respawn)
            self.x, self.y, self.z, self.h = p.x, p.y, p.z, p.heading
        now = time.time()                                                # Vorausberechnung: kein Stehenbleiben zwischen verspäteten Paketen
        if self.src is None or math.hypot(p.x - self.src[0], p.y - self.src[1]) > 8.0:
            self.src, self.src_t, self.vel = (p.x, p.y), now, (0.0, 0.0)
        elif (p.x, p.y) != self.src:
            dts = now - self.src_t
            if 0.004 < dts < 0.6 and p.moving:
                nv = ((p.x - self.src[0]) / dts, (p.y - self.src[1]) / dts)
                self.vel = (self.vel[0] * 0.65 + nv[0] * 0.35, self.vel[1] * 0.65 + nv[1] * 0.35)
            else:
                self.vel = (0.0, 0.0)
            self.src, self.src_t = (p.x, p.y), now
        ahead = min(0.18, now - self.src_t) if (p.moving and p.hp > 0) else 0.0
        if not p.moving:
            self.vel = (0.0, 0.0)
        tx, ty = p.x + self.vel[0] * ahead, p.y + self.vel[1] * ahead
        a = min(1.0, 15.0 * dt)
        self.x += (tx - self.x) * a
        self.y += (ty - self.y) * a
        self.z += (p.z - self.z) * a
        self.h += ((p.heading - self.h + 180.0) % 360.0 - 180.0) * a
        r = self.root
        r.setPos(self.x, self.y, self.z)
        (r.hide if p.heli >= 0 else r.show)()                           # Piloten sieht man im Cockpit nicht
        if p.hp <= 0:                                                    # umfallen
            self.dead_t += dt
            t = min(1.0, self.dead_t / 0.5)
            r.setHpr(self.h, 90.0 * t * (2 - t), 0)
            r.setSz(1.0)
            r.setColorScale(0.7, 0.7, 0.7, 1)
            self.bar.hide()
            self.rl_t = self.th_t = self.swing = 0.0
            self.pose_arms(0.0)
            return
        self.dead_t = 0.0
        hg = getattr(p, "hold_gad", -1)
        self.show_held(getattr(p, "cur", 0))
        self.show_gadget(hg)
        for k_, nd_ in self.held.items():                                # Gadget in der Hand: Waffe verschwindet
            if hg >= 0:
                nd_.hide()
        self.flash_t = max(0.0, self.flash_t - dt)
        self.kick = max(0.0, self.kick - 9.0 * dt)
        for k_, fl_ in self.flash.items():
            (fl_.show if (self.flash_t > 0 and k_ == self.held_cur and hg < 0) else fl_.hide)()
        r.clearColorScale()
        r.setHpr(self.h, 0, 0)
        r.setSz(1.0 - (1.0 - CROUCH_H / PLAYER_H) * p.crouch)               # geduckt
        mv = 1.0 if p.moving else 0.0
        self.phase += mv * 14.0 * dt
        sw = math.sin(self.phase) * mv
        self.legL.setP(sw * 40)
        self.legR.setP(-sw * 40)
        self.torso.setZ(0.75 + abs(math.sin(self.phase)) * 0.05 * mv)
        self.torso.setR(p.lean / LEAN_MAX * 14.0)          # Lehnen: Oberkörper kippt zur Seite
        self.pose_arms(dt)
        if not self.slung:                                  # Rückstoss: Waffe ruckt nach hinten und kippt hoch
            sr_ = SOLDIER_SH[1]
            self.gun.setPos(-sr_[0], -sr_[1] - 0.07 * self.kick, -sr_[2])
            self.gun.setP(7.0 * self.kick)


# --------------------------------------------------------------- Ton
SR = 22050


def synth_sounds():
    """Alle Geräusche werden beim Start errechnet (keine Audiodateien nötig). Gibt {Name: [Samples -1..1]} zurück."""
    rng = random.Random(7)
    tp = 2 * math.pi

    def noise(n):
        return [rng.uniform(-1.0, 1.0) for _ in range(n)]

    def lowpass(x, a):
        y, out = 0.0, []
        for v in x:
            y += a * (v - y)
            out.append(y)
        return out

    def env(n, k):
        return [math.exp(-k * i / SR) for i in range(n)]

    def sweep(n, f0, f1, k):                       # Sinus, dessen Frequenz von f0 nach f1 absinkt
        ph, out = 0.0, []
        for i in range(n):
            t = i / SR
            ph += tp * (f1 + (f0 - f1) * math.exp(-k * t)) / SR
            out.append(math.sin(ph))
        return out

    def mix(*parts):
        n = max(len(p) for p, _g in parts)
        out = [0.0] * n
        for p, g in parts:
            for i, v in enumerate(p):
                out[i] += v * g
        return out

    def mul(a, b):
        return [x * y for x, y in zip(a, b)]

    def delay(x, off, g):                          # Hall: verzögerte, leisere Kopie
        o = int(off * SR)
        out = list(x) + [0.0] * o
        for i, v in enumerate(x):
            out[i + o] += v * g
        return out

    def norm(x, peak):
        m = max(abs(v) for v in x) or 1.0
        return [v * peak / m for v in x]

    def gun(dur, crack_k, body_a, body_k, f0, f1, tk, echo=0.0, peak=0.9):
        n = int(dur * SR)
        s = mix((mul(noise(n), env(n, crack_k)), 1.0),
                (mul(lowpass(noise(n), body_a), env(n, body_k)), 1.1),
                (mul(sweep(n, f0, f1, tk), env(n, tk * 0.7)), 0.9))
        if echo:
            s = delay(s, echo, 0.35)
        return norm(s, peak)

    out = {}
    n = int(0.16 * SR)
    out["step_soft"] = norm(mix((mul(lowpass(noise(n), 0.16), env(n, 30)), 1.0),
                                (mul(sweep(n, 85, 55, 40), env(n, 35)), 0.9)), 0.6)
    n = int(0.14 * SR)                                                     # Stein: hartes Klacken mit hellem "Tock"
    out["step_hard"] = norm(mix((mul(noise(n), env(n, 130)), 0.8),
                                (mul(sweep(n, 950, 480, 40), env(n, 48)), 0.8),
                                (mul(sweep(n, 170, 110, 50), env(n, 40)), 0.5)), 0.7)
    n = int(0.04 * SR)
    n = int(0.22 * SR)
    out["swing"] = norm(mix((mul(lowpass(noise(n), 0.10), [math.sin(math.pi * i / n) ** 2 for i in range(n)]), 1.0),
                            (mul(sweep(n, 420, 150, 9), env(n, 18)), 0.25)), 0.7)
    n = int(0.12 * SR)
    out["thud"] = norm(mix((mul(sweep(n, 220, 70, 30), env(n, 38)), 1.0), (mul(lowpass(noise(n), 0.2), env(n, 60)), 0.6)), 0.95)
    out["click"] = norm(mix((mul(sweep(n, 2600, 1600, 80), env(n, 110)), 1.0),
                            (mul(noise(n), env(n, 300)), 0.3)), 0.5)
    # Nachladen: Magazin raus (Klick + Schaben), Magazin rein (Schlag + Klick), Durchladen (Schaben + Klack)
    N = int(1.4 * SR)
    rl = [0.0] * N

    def ev(t0, part, g):
        o = int(t0 * SR)
        for i, v in enumerate(part):
            if o + i < N:
                rl[o + i] += v * g

    def click_part(f, dur=0.03, k=130):
        m = int(dur * SR)
        return mix((mul(sweep(m, f, f * 0.7, 60), env(m, k)), 1.0), (mul(noise(m), env(m, 250)), 0.4))

    def scrape(dur, a):
        m = int(dur * SR)
        return mul(lowpass(noise(m), a), [math.sin(math.pi * i / m) for i in range(m)])

    ev(0.10, click_part(1900), 0.9)
    ev(0.16, scrape(0.14, 0.30), 0.5)
    m = int(0.08 * SR)
    ev(0.62, mix((mul(sweep(m, 210, 90, 50), env(m, 38)), 1.0), (mul(noise(m), env(m, 160)), 0.5)), 1.0)
    ev(0.66, click_part(2300), 0.7)
    ev(0.95, scrape(0.16, 0.35), 0.6)
    ev(1.12, click_part(1400, 0.05, 90), 1.0)
    ev(1.16, mix((mul(sweep(m, 160, 80, 40), env(m, 40)), 1.0),), 0.6)
    out["reload"] = norm(rl, 0.8)
    out["pistol"] = gun(0.30, 70, 0.35, 18, 200, 80, 40)
    out["rifle"] = gun(0.35, 55, 0.25, 14, 140, 60, 30)
    out["shotgun"] = gun(0.70, 40, 0.15, 7, 90, 40, 12)
    out["heavy"] = gun(1.00, 45, 0.20, 5, 70, 35, 8, echo=0.18)
    n = int(0.8 * SR)
    out["railgun"] = norm(mix((mul(sweep(n, 2200, 180, 6), env(n, 6)), 1.0),
                              (mul(lowpass(noise(n), 0.3), env(n, 10)), 0.5),
                              (mul(sweep(n, 90, 40, 10), env(n, 7)), 0.9)), 0.9)
    n = int(1.0 * SR)
    sh = [math.sin(math.pi * i / n) ** 0.6 for i in range(n)]              # Abschuss: anschwellendes Zischen
    out["rocket"] = norm(mix((mul(lowpass(noise(n), 0.12), sh), 1.0),
                             (mul(sweep(n, 120, 70, 3), env(n, 3)), 0.8)), 0.9)
    n = int(2.4 * SR)
    ex, y, a = [], 0.0, 0.5
    for i in range(n):                                                      # Tiefpass, der sich zudreht
        t = i / SR
        y += max(0.03, a * math.exp(-t * 2.2)) * (rng.uniform(-1, 1) - y)
        ex.append(y)
    out["explosion"] = norm(delay(mix((mul(ex, env(n, 2.0)), 1.6),
                                      (mul(sweep(n, 70, 32, 3), env(n, 2.4)), 1.0),
                                      (mul(noise(n), env(n, 60)), 0.8)), 0.22, 0.3), 0.95)
    # Helikopter: Rotorschlag (12 Hz) auf Rauschen und tiefem Brummen, nahtlos wiederholbar
    N, F = SR, int(0.06 * SR)
    base = []
    nz = lowpass(noise(N + F), 0.22)
    for i in range(N + F):
        t = i / SR
        chop = 0.35 + 0.65 * max(0.0, math.sin(tp * 12 * t)) ** 2
        base.append(nz[i] * chop * 1.6 + math.sin(tp * 48 * t) * 0.35 + math.sin(tp * 96 * t) * 0.2 * chop)
    loop = base[:N]
    for i in range(F):                                                      # Naht überblenden
        k = i / F
        loop[i] = loop[i] * k + base[N + i] * (1 - k)
    out["heli"] = norm(loop, 0.8)
    # Tomahawk-Anflug: tiefes Triebwerksdröhnen (nahtlos wiederholbar) und Pfeifen kurz vor dem Einschlag
    N, F = SR, int(0.08 * SR)
    nz = lowpass(noise(N + F), 0.05)
    nz2 = lowpass(noise(N + F), 0.25)
    base = [nz[i] * 2.2 + nz2[i] * 0.35 + math.sin(tp * 38 * i / SR) * 0.25 for i in range(N + F)]
    loop = base[:N]
    for i in range(F):
        k = i / F
        loop[i] = loop[i] * k + base[N + i] * (1 - k)
    out["jet"] = norm(loop, 0.85)
    n = int(2.8 * SR)
    wh, ph = [], 0.0
    for i in range(n):
        t = i / SR
        ph += tp * (2400 - 1700 * (t / 2.8) ** 0.7) / SR
        a = min(1.0, t / 0.4) * (0.4 + 0.6 * t / 2.8)
        wh.append(math.sin(ph) * a)
    out["whistle"] = norm(mix((wh, 1.0), (mul(lowpass(noise(n), 0.4), [0.15 + 0.3 * i / n for i in range(n)]), 0.4)), 0.8)
    return out


STONE_MATS = ("metal", "concrete")          # Netz-Karten: diese Render-Gruppen klingen nach Stein, alles andere nach Gras


def _stone_grid(world):
    """Dreiecke der Stein-Gruppen (Basen, Beton) in einem 4-m-Raster (nur Netz-Karten); einmal pro Karte."""
    grid = getattr(world, "_stone_grid", None)
    if grid is None:
        grid = {}
        mp = getattr(world, "map", None)
        mesh = mp.get("mesh") if isinstance(mp, dict) else None
        for mat, _tint, rv, _rn, rt in (mesh["render"] if mesh else ()):
            if mat not in STONE_MATS:
                continue
            for ia, ib, ic in rt:
                a, b, c = rv[ia], rv[ib], rv[ic]
                det = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1])
                if abs(det) < 1e-9:
                    continue
                t = (a, b, c, det)
                for i in range(int(min(a[0], b[0], c[0]) // 4), int(max(a[0], b[0], c[0]) // 4) + 1):
                    for j in range(int(min(a[1], b[1], c[1]) // 4), int(max(a[1], b[1], c[1]) // 4) + 1):
                        grid.setdefault((i, j), []).append(t)
        try:
            world._stone_grid = grid
        except Exception:
            pass
    return grid


def surface_kind(world, x, y, z):
    """'wood' (Holzboden), 'hard' (Stein, Metall, Treppe, Deckung) oder 'grass' (alles andere)."""
    if getattr(world, "cm", None) is not None:             # Netz-Karte: Material des Dreiecks unter den Füssen
        for a, b, c, det in _stone_grid(world).get((int(x // 4), int(y // 4)), ()):
            l1 = ((b[1] - c[1]) * (x - c[0]) + (c[0] - b[0]) * (y - c[1])) / det
            l2 = ((c[1] - a[1]) * (x - c[0]) + (a[0] - c[0]) * (y - c[1])) / det
            l3 = 1.0 - l1 - l2
            if l1 >= -0.01 and l2 >= -0.01 and l3 >= -0.01 and abs(l1 * a[2] + l2 * b[2] + l3 * c[2] - z) < 0.6:
                return "hard"
        return "grass"
    if z < -1.0 and getattr(world, "tunnels", None) and world.in_tunnel(x, y):
        return "hard"                                          # Tunnelgang (nicht jede Senke unter 1 m)
    if z > world.height(x, y, z + 0.2) + 0.12:
        return "hard"
    for f in getattr(world, "floors", ()):
        if f[0] <= x <= f[2] and f[1] <= y <= f[3]:
            return "wood" if len(f) > 4 and f[4] == WOOD_F else "hard"
    return "grass"


def surface_is_hard(world, x, y, z):
    """Steht man auf Stein (Gebäudeboden, Treppe, Mauerkrone, Deckungsblock, Tunnel) statt auf Erde?"""
    return surface_kind(world, x, y, z) in ("hard", "wood")


