class Sfx:
    """Geräusche: Schüsse, Schritte, Explosionen, Helikopter. Positionsabhängig (Lautstärke und Richtung)
    über OpenAL; fehlt eine Audioausgabe, läuft das Spiel ohne Ton weiter."""

    POOL = {"step_soft": 5, "step_hard": 5, "pistol": 4, "rifle": 8, "shotgun": 3, "heavy": 3,
            "railgun": 3, "rocket": 3, "explosion": 6, "click": 3, "reload": 2, "whistle": 1, "swing": 2, "thud": 2}
    RANGE = {"step_soft": 28.0, "step_hard": 32.0, "pistol": 160.0, "rifle": 190.0, "shotgun": 170.0,
             "heavy": 260.0, "railgun": 260.0, "rocket": 180.0, "explosion": 320.0, "heli": 260.0,
             "click": 50.0, "reload": 50.0, "whistle": 700.0, "jet": 2500.0, "swing": 60.0, "thud": 70.0}
    MIN = {"step_soft": 3.0, "step_hard": 3.0, "pistol": 12.0, "rifle": 14.0, "shotgun": 14.0,
           "heavy": 20.0, "railgun": 20.0, "rocket": 14.0, "explosion": 30.0, "heli": 18.0,
           "click": 40.0, "reload": 40.0, "whistle": 120.0, "jet": 150.0, "swing": 8.0, "thud": 10.0}

    def __init__(self, game):
        self.game = game
        self.ok = False
        self.muted = False
        self.a3d = None
        self.pool, self.rr, self.paths = {}, {}, {}
        self.walk = {}                 # Spieler-ID -> [x, y, zurückgelegte Strecke]
        self.heli_snd = {}             # Heli-ID -> (Sound, Knoten)
        self.heli_mg = {}              # Heli-ID -> (letzter MG-Vorrat, Sperrzeit)
        self.nuke = None               # [Sound, Knoten, Lautstärke] des Tomahawk-Countdowns
        self.jet = None                # Tomahawk-Anflug: (Sound, Knoten), Dauerschleife
        self.chat = None               # Funkgeräusch aus dem Kontrollraum (Sound, Knoten)
        self.music_path, self.music, self.music_v = None, None, 0.0     # Menümusik (Schleife)
        self.music_gain = 1.0          # Einstellung "Musik-Lautstärke" (0..1)
        if not REAL_PANDA:
            return
        try:
            import tempfile
            import wave
            from array import array
            from panda3d.core import Filename
            tmp = tempfile.mkdtemp(prefix="spiel_ton_")
            for name, data in synth_sounds().items():
                p = os.path.join(tmp, name + ".wav")
                with wave.open(p, "wb") as f:
                    f.setnchannels(1)
                    f.setsampwidth(2)
                    f.setframerate(SR)
                    f.writeframes(array("h", [int(max(-1.0, min(1.0, v)) * 32000) for v in data]).tobytes())
                own = find_sound(name)                          # eigene Datei in sounds/ ersetzt das synthetische Geräusch
                if own:
                    print("Eigener Ton:", name, "<-", own)
                self.paths[name] = Filename.fromOsSpecific(own or p).getFullpath()
            import base64
            import zlib
            for name, b64 in list(STEP_CLIPS.items()) + list(WEAPON_CLIPS.items()):
                p = os.path.join(tmp, name + ".wav")
                with open(p, "wb") as f:
                    f.write(zlib.decompress(base64.b64decode("".join(b64))))
                own = find_sound(name)
                self.paths[name] = Filename.fromOsSpecific(own or p).getFullpath()
            own = find_sound("menu_music")                      # Menümusik als Datei (Musik wird gestreamt, nicht komplett geladen)
            mp = own or os.path.join(tmp, "menu_music.mp3")
            if not own:
                with open(mp, "wb") as f:
                    f.write(base64.b64decode("".join(MENU_MUSIC)))
            self.music_path = Filename.fromOsSpecific(mp).getFullpath()
            mgr = game.sfxManagerList[0]
            try:
                from direct.showbase.Audio3DManager import Audio3DManager
                self.a3d = Audio3DManager(mgr, game.camera)
                self.a3d.setDopplerFactor(0.0)
                self.a3d.setDropOffFactor(1.0)
            except Exception as e:
                print("3D-Ton nicht verfügbar:", e)
                self.a3d = None
            for name in WEAPON_CLIPS:
                self.POOL[name] = {"sniper": 3, "hitmark": 4, "ar_single": 24, "chatter": 0, "melee_swing": 3, "melee_punch": 3, "tur_single": 16, "flak_single": 6, "nuke": 0, "breath_in": 1, "breath_out": 1, "heartbeat": 3, "expl_c4": 4, "expl_gren": 4, "gren_throw": 3, "pistol_single": 6, "revolver_single": 6, "smg_single": 20, "reload_rifle": 2, "reload_pistol": 2, "reload_revolver": 2, "reload_smg": 2, "shotgun_shot": 3}.get(name, 2)
                self.RANGE[name] = {"sniper": 320.0, "ar_single": 190.0, "chatter": 20000.0, "melee_swing": 60.0, "melee_punch": 70.0, "tur_single": 260.0, "flak_single": 300.0, "nuke": 2000.0, "expl_c4": 320.0, "expl_gren": 260.0, "gren_throw": 45.0, "pistol_single": 150.0, "revolver_single": 210.0, "smg_single": 160.0, "shotgun_shot": 230.0}.get(name, 50.0)
                self.MIN[name] = {"sniper": 24.0, "ar_single": 14.0, "chatter": 10000.0, "melee_swing": 8.0, "melee_punch": 10.0, "tur_single": 20.0, "flak_single": 25.0, "nuke": 2000.0, "expl_c4": 30.0, "expl_gren": 24.0, "gren_throw": 8.0, "pistol_single": 12.0, "revolver_single": 16.0, "smg_single": 12.0, "shotgun_shot": 18.0}.get(name, 40.0)
            for name in STEP_CLIPS:
                self.POOL[name] = 3
                self.RANGE[name], self.MIN[name] = self.RANGE["step_soft"], self.MIN["step_soft"]
            for name, n in self.POOL.items():
                self.pool[name] = [self.make(name) for _ in range(n)]
                self.rr[name] = 0
            self.ok = True
        except Exception as e:
            print("Ton nicht verfügbar:", e)
            self.ok = False

    def make(self, name):
        snd = self.a3d.loadSfx(self.paths[name]) if self.a3d else self.game.sfxManagerList[0].getSound(self.paths[name])
        node = self.game.render.attachNewNode("ton")
        if self.a3d:
            self.a3d.attachSoundToObject(snd, node)
            try:
                self.a3d.setSoundMinDistance(snd, self.MIN.get(name, 10.0))
                self.a3d.setSoundMaxDistance(snd, self.RANGE.get(name, 150.0))
            except Exception:
                pass
        return snd, node

    def cam(self):
        p = self.game.camera.getPos(self.game.render)
        return (p[0], p[1], p[2])

    def play(self, name, pos=None, vol=1.0, rate=1.0):
        if not self.ok or self.muted or name not in self.pool:
            return
        try:
            cam = self.cam()
            pos = pos or cam
            d = math.dist(pos, cam)
            if d > self.RANGE.get(name, 150.0):
                return
            snd, node = self.pool[name][self.rr[name]]
            self.rr[name] = (self.rr[name] + 1) % len(self.pool[name])
            if self.a3d is None:
                m = self.MIN.get(name, 10.0)
                vol *= 1.0 if d <= m else max(0.0, 1.0 - (d - m) / (self.RANGE.get(name, 150.0) - m)) ** 1.6
            node.setPos(*pos)
            snd.setVolume(max(0.0, min(1.0, vol)))
            snd.setPlayRate(rate)
            snd.play()
            return snd
        except Exception:
            pass
        return None

    def jet_sound(self, pos, left=99.0):
        """Dröhnen der anfliegenden Tomahawk-Rakete (pos = None: aus). Im Anflug nur leise im Hintergrund;
        erst in den letzten TOMA_LOUD_T Sekunden dreht es auf TOMA_JET_VOL auf ("gleich knallt's")."""
        if not self.ok:
            return
        try:
            if pos is None or self.muted:
                if self.jet is not None:
                    self.jet[0].stop()
                return
            if self.jet is None:
                self.jet = self.make("jet")
                self.jet[0].setLoop(True)
            snd, node = self.jet
            node.setPos(*pos)
            k = max(0.0, min(1.0, 1.0 - left / TOMA_LOUD_T))          # 0 bis zu den letzten Sekunden, dann bis 1
            vol = TOMA_JET_QUIET + (TOMA_JET_VOL - TOMA_JET_QUIET) * k * k
            snd.setVolume(max(0.0, min(1.0, vol)))
            snd.setPlayRate(0.8 + 0.35 * k)
            if snd.status() != 2:
                snd.play()
        except Exception:
            pass

    MUSIC_VOL = 0.45

    def menu_music(self, dt, on):
        """Menümusik in Endlosschleife: blendet im Hauptmenü ein und beim Spielstart aus."""
        if not self.ok or self.music_path is None:
            return
        want = self.MUSIC_VOL * self.music_gain if (on and not self.muted) else 0.0
        if self.music is None:
            if want <= 0.0:
                return
            try:
                self.music = self.game.loader.loadMusic(self.music_path)
            except Exception:
                try:
                    self.music = self.game.sfxManagerList[0].getSound(self.music_path)
                except Exception:
                    self.music_path = None
                    return
            self.music.setLoop(True)
        rate = 1.0 / (1.5 if want > self.music_v else 0.5)
        step = self.MUSIC_VOL * rate * dt
        self.music_v = min(want, self.music_v + step) if want > self.music_v else max(want, self.music_v - step)
        try:
            if self.music_v > 0.0:
                self.music.setVolume(self.music_v)
                if self.music.status() != 2:
                    self.music.play()
            elif self.music.status() == 2:
                self.music.stop()
        except Exception:
            pass

    def silence(self):
        if self.music is not None:
            try:
                self.music.stop()
            except Exception:
                pass
        self.music_v = 0.0
        if self.nuke:
            try:
                self.nuke[0].stop()
            except Exception:
                pass
        self.nuke = None
        if self.jet is not None:
            try:
                self.jet[0].stop()
            except Exception:
                pass
        if self.chat:
            try:
                self.chat[0].stop()
            except Exception:
                pass
        self.chat = None                                    # die Knoten werden mit der Szene entfernt -> beim nächsten Spiel neu
        for snd, _node in self.heli_snd.values():
            try:
                snd.stop()
            except Exception:
                pass
        self.heli_snd.clear()
        self.heli_mg.clear()
        for snd, _node in self.heli_snd.values():
            try:
                snd.stop()
            except Exception:
                pass
        self.walk.clear()

    # ----- Ereignisse
    def shot(self, wi, pid):
        g = self.game
        pl = g.world.players.get(pid)
        own = pid == g.my_id
        if pl is None and not own:
            return
        pos = None if own else (pl.x, pl.y, pl.z + 1.4)
        name = WEAPONS[wi].name if 0 <= wi < len(WEAPONS) else ""
        kind, rate = {"Pistole": ("pistol", 1.0), "Revolver": ("pistol", 0.78), "Sturmgewehr": ("rifle", 1.0),
                      "Maschinenpistole": ("rifle", 1.3), "Minigun": ("rifle", 1.12),
                      "Schrotflinte": ("shotgun_shot", 1.0), "Scharfschütze": ("sniper", 1.0),
                      "Railgun": ("railgun", 1.0), "Raketenwerfer": ("rocket", 1.0)}.get(name, ("rifle", 1.0))
        if name == "Sturmgewehr" and "ar_single" in self.pool:
            # Jeder Schuss spielt die Einzelschuss-Aufnahme bis zum Ende; bei Dauerfeuer überlagern sich die Schüsse.
            self.play("ar_single", pos, 0.45 if own else 0.6, g.prng.uniform(0.985, 1.015))
            return
        single = {"Pistole": ("pistol_single", 0.8, 0.9), "Revolver": ("revolver_single", 0.75, 0.85),
                  "Maschinenpistole": ("smg_single", 0.55, 0.65)}.get(name)
        if single and single[0] in self.pool:                   # Einzelschuss-Aufnahme, jeder Schuss klingt aus -> Überlagerung
            self.play(single[0], pos, single[1] if own else single[2], g.prng.uniform(0.985, 1.015))
            return
        r = g.prng.uniform(0.96, 1.04) if kind not in ("sniper", "shotgun_shot") else g.prng.uniform(0.99, 1.01)
        self.play(kind, pos, 0.85 if own else 1.0, rate * r)

    def reload(self, wi):
        w = WEAPONS[wi] if 0 <= wi < len(WEAPONS) else None
        if w and w.name == SG_NAME and "sg_open" in self.pool:
            return                                              # die Klänge kommen im Takt der Animation (Game.update_views)
        key = {"Scharfschütze": "reload_sniper", "Sturmgewehr": "reload_rifle", "Pistole": "reload_pistol",
                                                  "Revolver": "reload_revolver", "Maschinenpistole": "reload_smg"}.get(w.name) if w else None
        if key and key in self.pool:
            self.stop_reload()
            snd = self.play(key, None, 0.9, 1.0)                    # Aufnahme auf die Nachladezeit der Waffe abgestimmt
            self.rl_snd = snd
            me = self.game.world.players.get(self.game.my_id)
            self.rl_mag = me.guns[wi].mag if me is not None else 0
            self.rl_wi = wi
            return
        rate = max(0.75, min(1.25, 1.3 / w.reload)) if w else 1.0
        self.play("reload", None, 0.7, rate)

    def hitmark(self):
        """Treffer-Ton (eigener Treffer, Kill): höchstens einmal alle 60 ms, damit Treffer + Kill nicht doppelt klingen."""
        import time
        now = time.monotonic()
        if now - getattr(self, "hm_t", 0.0) < 0.06:
            return
        self.hm_t = now
        self.play("hitmark", None, 0.5, 1.0)

    def stop_reload(self):
        snd, self.rl_snd = getattr(self, "rl_snd", None), None
        if snd is not None:
            try:
                snd.stop()
            except Exception:
                pass

    def melee(self, pid, hit):
        g = self.game
        pl = g.world.players.get(pid)
        own = pid == g.my_id
        if pl is None and not own:
            return
        pos = None if own else (pl.x, pl.y, pl.z + 1.2)
        if "melee_swing" in self.pool:                          # eigene Aufnahmen: Schlag in die Luft, Treffer (neben dem Hitmarker)
            self.play("melee_swing", pos, 0.6, g.prng.uniform(0.97, 1.03))
            if hit:
                self.play("melee_punch", pos, 0.9, g.prng.uniform(0.97, 1.03))
            return
        self.play("swing", pos, 0.7, g.prng.uniform(0.92, 1.1))
        if hit:
            self.play("thud", pos, 0.9, g.prng.uniform(0.92, 1.08))

    def ui_click(self):
        self.play("click", None, 0.45, self.game.prng.uniform(0.95, 1.08))

    def turret(self, tid):
        ts = self.game.world.turrets
        if not (0 <= tid < len(ts)):
            return
        t = ts[tid]
        if "tur_single" in self.pool:                            # Einzelschuss-Aufnahmen, überlagern sich bei Dauerfeuer
            own = self.game.player.mount == tid
            pos = None if own else (t.x, t.y, t.z)
            if t.kind == "flak":
                self.play("flak_single", pos, 0.8 if own else 0.9, self.game.prng.uniform(0.99, 1.01))
            else:
                self.play("tur_single", pos, 0.45 if own else 0.5, self.game.prng.uniform(0.985, 1.015))
            return
        pos = (t.x, t.y, t.z)
        if t.kind == "flak":
            self.play("heavy", pos, 1.0, 0.8)
        else:
            self.play("rifle", pos, 1.0, 0.8 * self.game.prng.uniform(0.96, 1.04))

    def explosion(self, pos, r, wi=None):
        key = {WI_C4: "expl_c4", WI_CLAY: "expl_c4", WI_GRENADE: "expl_gren"}.get(wi)
        if key and key in self.pool:                            # eigene Aufnahmen: C4/Claymore bzw. Handgranate
            self.play(key, tuple(pos), 0.9, 1.0)
            return
        vol = max(0.6, min(1.0, 0.45 + r * 0.09))
        self.play("explosion", tuple(pos), vol, max(0.7, min(1.2, 1.3 - r * 0.05)))

    def heli_rocket(self, pid):
        for hc in self.game.world.helis:
            if hc.driver == pid:
                self.play("rocket", (hc.x, hc.y, hc.z), 1.0, 0.9)
                return

    # ----- pro Bild
    def update(self, dt):
        if not self.ok or self.muted:
            return
        try:
            self.steps(dt)
            self.nuke_sound(dt)
            self.control_room(dt)
            if getattr(self, "rl_snd", None) is not None:            # Nachladen abgebrochen (Waffenwechsel, Tod) -> Ton stoppen
                me = self.game.world.players.get(self.game.my_id)
                if me is None or me.hp <= 0:
                    self.stop_reload()
                elif me.reload_t <= 0:
                    if me.guns[self.rl_wi].mag <= self.rl_mag:                # Magazin nicht gefüllt = abgebrochen
                        self.stop_reload()
                    else:
                        self.rl_snd = None                           # regulär fertig: Ton läuft aus
            self.helis(dt)
        except Exception:
            pass

    def steps(self, dt):
        g, world = self.game, self.game.world
        cam = self.cam()
        seen = set()
        for pid, pl in world.players.items():
            seen.add(pid)
            st = self.walk.get(pid)
            if st is None or pl.hp <= 0:
                self.walk[pid] = [pl.x, pl.y, STEP_READY, 0.0, 0.0, {}, None, "grass", 0.0, None]
                continue
            d = math.hypot(pl.x - st[0], pl.y - st[1])
            st[0], st[1] = pl.x, pl.y
            if dt > 0:
                st[3] += (min(d / dt, 20.0) - st[3]) * min(1.0, dt * 8.0)      # geglättete Geschwindigkeit
            if d > 3.0:                                                         # Teleport
                st[2], st[6], st[9] = STEP_READY, None, None
                continue
            if pl.vehicle >= 0 or pl.heli >= 0 or pl.mount >= 0:
                st[2], st[4], st[6], st[9] = STEP_READY, 0.0, None, None
                continue
            if not pl.moving:                                                   # Stillstand: der nächste Schritt kommt sofort
                st[2], st[4], st[6], st[9] = STEP_READY, 0.0, None, None
                st[5].clear()                                                   # nächste Abfolge beginnt wieder mit Impuls 1
                continue
            if not getattr(pl, "on_ground", True):                              # kurz in der Luft (Hänge): Strecke bleibt erhalten
                st[4] += dt
                if st[4] > 0.3:
                    st[2], st[6], st[9] = STEP_READY, None, None
                elif st[2] < STEP_READY:
                    st[2] += d
                continue
            st[4] = 0.0
            inst = d / dt if dt > 0 else 0.0
            if st[6] is None and st[9] is None:
                st[3] = max(st[3], min(inst, 12.0))               # Start: gleich die echte Geschwindigkeit nehmen
            run = st[3] > RUN_SPEED and getattr(pl, "crouch", 0.0) < 0.3
            st[8] -= dt
            if st[8] <= 0.0 or st[6] is None:
                st[7], st[8] = surface_kind(world, pl.x, pl.y, pl.z), 0.1
            loop = None
            if max(st[3], d / dt if dt > 0 else 0.0) > 0.8:
                if st[7] == "grass":
                    loop = "grass_run" if run else "grass"
                elif st[7] == "hard":
                    loop = "stone_run" if run else "stone_walk"
            if loop != st[9]:
                st[6], st[9] = None, loop                                       # Wechsel (Gehen/Rennen/Untergrund): Schleife neu
            if loop is not None:
                period, evs, lvol = STEP_LOOPS[loop]
                prev = evs[0][0] - 1e-4 if st[6] is None else st[6]
                new = prev + dt * (1.0 - 0.5 * getattr(pl, "crouch", 0.0))
                hits = [nm for t_, nm in evs if prev < t_ <= new]
                if new >= period:
                    new -= period
                    hits += [nm for t_, nm in evs if t_ <= new]
                st[6] = new
                if hits and math.hypot(pl.x - cam[0], pl.y - cam[1]) <= 34.0:
                    vol = (0.55 if pid == g.my_id else 0.8) * (1.0 - 0.6 * getattr(pl, "crouch", 0.0))
                    pos = None if pid == g.my_id else (pl.x, pl.y, pl.z + 0.1)
                    for nm in hits:
                        self.play(nm, pos, vol * lvol, g.prng.uniform(0.98, 1.02))
                st[2] = STEP_READY
                continue
            st[6] = None
            st[2] = st[2] if st[2] >= STEP_READY else st[2] + d
            stride = RUN_STRIDE if run else 1.9
            if st[2] >= stride:
                if math.hypot(pl.x - cam[0], pl.y - cam[1]) > 34.0:
                    st[2] = 0.0 if st[2] >= STEP_READY else st[2] - stride
                    continue
                kind = surface_kind(world, pl.x, pl.y, pl.z)
                need = STEP_STRIDE.get((kind, run), stride)
                if st[2] < need:
                    continue
                st[2] = 0.0 if st[2] >= STEP_READY else st[2] - need
                vol = (0.55 if pid == g.my_id else 0.8) * (1.0 - 0.6 * getattr(pl, "crouch", 0.0))
                pos = None if pid == g.my_id else (pl.x, pl.y, pl.z + 0.1)
                names = STEP_SETS.get((kind, run)) or (STEP_SETS.get((kind, False)) if kind != "hard" else None)
                if names and names[0] in self.pool:
                    k = st[5].get((kind, run), -1) + 1
                    if kind != "grass" or run:                 # Gras (Gehen): strikt abwechselnd wie in der Aufnahme
                        k = (k + g.prng.randrange(max(1, len(names) - 1))) if len(names) > 1 else 0
                    k %= len(names)
                    st[5][(kind, run)] = k
                    self.play(names[k], pos, vol * STEP_VOL[kind] * (1.15 if run else 1.0), g.prng.uniform(0.96, 1.04))
                else:
                    self.play("step_hard" if kind == "hard" else "step_soft", pos, vol, g.prng.uniform(0.9, 1.12))
        for pid in [p for p in self.walk if p not in seen]:
            del self.walk[pid]

    CHAT_REF = 4.0         # m: bis hierhin volle Lautstärke (Raumgrösse), dahinter 1/r wie bei einer Punktquelle
    CHAT_VOL = 0.8
    CHAT_AIR = 55.0        # m: zusätzliche Luftdämpfung exp(-r/55)

    WALL_DAMP = 0.35       # Schalldurchgang je durchquerter Wand (ca. -9 dB)

    def wall_factor(self, world, p0, p1):
        """Dämpfung durch Wände zwischen Quelle und Hörer: jede Wand lässt nur einen Teil des Schalls durch."""
        try:
            n = 0
            for b in world.boxes_near(p0[0], p0[1], p1[0], p1[1]):
                if seg_box(p0, p1, b) is not None:
                    n += 1
            return max(0.03, self.WALL_DAMP ** min(n, 4))
        except Exception:
            return 1.0

    def control_room(self, dt):
        """Dauerhaftes Funkgeräusch aus dem Kontrollraum (Tomahawk-Knopf und Zeitwahl). Die Lautstärke fällt mit der
        Entfernung physikalisch ab: Schalldruck ~ 1/r (-6 dB je Verdopplung) plus leichte Luftdämpfung. Die
        Richtung (links/rechts) übernimmt der 3D-Ton; ohne 3D-Ton wird nur die Lautstärke geregelt."""
        world = self.game.world
        b, tp = getattr(world, "button", None), getattr(world, "timer_panel", None)
        if "chatter" not in self.paths or b is None or tp is None or b.x < -900:
            return
        if self.chat is None:
            snd, node = self.make("chatter")
            snd.setLoop(True)
            self.chat = (snd, node)
        snd, node = self.chat
        src = ((b.x + tp.x) * 0.5, (b.y + tp.y) * 0.5, (b.z + tp.z) * 0.5 + 1.3)
        node.setPos(*src)
        cam = self.cam()
        d = math.dist(src, cam)
        occ = self.wall_factor(world, src, cam)
        self.chat_occ = getattr(self, "chat_occ", occ) + (occ - getattr(self, "chat_occ", occ)) * min(1.0, 10.0 * dt)
        vol = self.chat_occ * self.CHAT_VOL * min(1.0, self.CHAT_REF / max(d, 0.01)) * math.exp(-max(0.0, d - self.CHAT_REF) / self.CHAT_AIR)
        snd.setVolume(max(0.0, min(1.0, vol)))
        if snd.status() != 2:
            snd.play()

    def nuke_sound(self, dt):
        """Tomahawk: ab Start des Countdowns bis zum Einschlag überall auf der Karte hörbar."""
        world = self.game.world
        on = getattr(world, "strike", 0) == 1 and "nuke" in self.paths
        ent = self.nuke
        if on and ent is None:
            snd, node = self.make("nuke")
            ent = self.nuke = [snd, node, 1.0]
            elapsed = max(0.0, float(getattr(world, "strike_dur", 0.0)) - float(getattr(world, "strike_t", 0.0)))
            snd.setVolume(0.55)
            try:
                if elapsed > 0.3:
                    snd.setTime(elapsed)                       # Spät beigetretener Spieler: an der richtigen Stelle einsteigen
            except Exception:
                pass
            snd.play()
        if ent is None:
            return
        snd, node, v = ent
        node.setPos(*self.cam())                               # immer am Hörer -> keine Abschwächung durch Entfernung
        if on:
            return
        v = max(0.0, v - dt / 0.35)                            # Einschlag / Abbruch: kurz ausblenden
        ent[2] = v
        snd.setVolume(0.55 * v)
        if v <= 0.0:
            snd.stop()
            self.nuke = None

    def helis(self, dt):
        g, world = self.game, self.game.world
        for hc in world.helis:
            on = hc.hp > 0 and hc.driver >= 0
            ent = self.heli_snd.get(hc.id)
            if ent is None and on:
                ent = self.heli_snd[hc.id] = self.make("heli")
                ent[0].setLoop(True)
            if ent is not None:
                snd, node = ent
                if on:
                    sp = min(1.0, hc.speed / HELI_VMAX)
                    own = hc.driver == g.my_id
                    node.setPos(*(self.cam() if own else (hc.x, hc.y, hc.z)))
                    vol = (0.45 if own else 0.9) * (0.65 + 0.35 * sp) * (0.8 if hc.ground else 1.0)
                    if self.a3d is None and not own:
                        d = math.dist((hc.x, hc.y, hc.z), self.cam())
                        vol *= max(0.0, 1.0 - d / self.RANGE["heli"]) ** 1.5
                    snd.setVolume(max(0.0, min(1.0, vol)))
                    snd.setPlayRate(0.85 + 0.3 * sp + (0.0 if hc.ground else 0.08))
                    if snd.status() != 2:                     # 2 = PLAYING
                        snd.play()
                else:
                    snd.stop()
            last, cd = self.heli_mg.get(hc.id, (hc.mg, 0.0))
            cd -= dt
            if hc.mg < last - 0.5 and cd <= 0 and hc.hp > 0:
                self.play("rifle", (hc.x, hc.y, hc.z), 0.9, 1.15)
                cd = 0.07
            self.heli_mg[hc.id] = (hc.mg, cd)


# --------------------------------------------------------------- Das Spiel
_EXP_MOD = None
_A2D = ("render", "aspect2d", "render2d", "a2dTopCenter", "a2dTopLeft", "a2dTopRight", "a2dBottomCenter",
        "a2dBottomLeft", "a2dBottomRight", "a2dLeftCenter", "a2dRightCenter")


def _pb_snapshot(g):
    """Zustand direkt nach ShowBase.__init__: alles danach gehört zum jeweiligen Spiel und wird beim Umschalten
    zwischen Hauptspiel und Experimental wieder abgeräumt."""
    nodes = [(n, set(n.getChildren())) for n in (getattr(g, nm, None) for nm in _A2D) if n is not None]
    return dict(keys=set(g.__dict__), tasks=set(g.taskMgr.getAllTasks()), later=set(g.taskMgr.getDoLaters()),
                events=set(g.getAllAccepting()), nodes=nodes)


def _pb_strip(g, leave_restore):
    """Räumt alles weg, was das bisherige Spiel an der Instanz hängen hat (das Fenster bleibt)."""
    snap = g._pb_base
    try:
        leave_restore()                                  # Sticky-Keys-Einstellung des alten Spiels zurücksetzen
    except Exception:
        pass
    for fn in (lambda: g.sfx.silence(), g.shutdown_net):
        try:
            fn()
        except Exception:
            pass
    for t in list(g.taskMgr.getAllTasks()):
        if t not in snap["tasks"]:
            g.taskMgr.remove(t)
    for t in list(g.taskMgr.getDoLaters()):
        if t not in snap["later"]:
            g.taskMgr.remove(t)
    for ev in list(g.getAllAccepting()):
        if ev not in snap["events"]:
            g.ignore(ev)
    for node, keep in snap["nodes"]:
        for ch in list(node.getChildren()):
            if ch not in keep:
                ch.removeNode()
    for k in list(g.__dict__):
        if k not in snap["keys"] and k != "_pb_base":
            del g.__dict__[k]


def _pb_rehook(g, title):
    try:
        ev = g.win.getCloseRequestEvent()                # Fensterkreuz soll das Spiel der neuen Klasse beenden
        g.ignore(ev)
        g.accept(ev, g.userExit)
    except Exception:
        pass
    try:
        props = WindowProperties()
        props.setTitle(title)
        g.win.requestProperties(props)
    except Exception:
        pass


def _exp_module():
    global _EXP_MOD
    if _EXP_MOD is None:
        import types
        path = _exp_path()
        if path is None:
            raise FileNotFoundError("Datei " + EXP_FILE + " nicht gefunden")
        with open(path, encoding="utf-8") as f:
            src = f.read()
        mod = types.ModuleType("polybash_experimental")
        mod.__file__ = os.path.abspath(__file__)         # Einstellungen/Log liegen neben spiel.py
        sys.modules["polybash_experimental"] = mod
        exec(compile(src, path, "exec"), mod.__dict__)
        mod.ShowBase = type("_AdoptBase", (mod.ShowBase,), {"__init__": lambda self: None})   # Fenster existiert schon
        mod.POLYBASH_BACK = _pb_back
        _EXP_MOD = mod
    return _EXP_MOD


def _pb_to_exp(task, g, spec):
    """Task (läuft vor dem Update-Task): Instanz wird zu Robins Game, dann Start nach spec."""
    try:
        mod = _exp_module()
    except Exception as e:
        g.menu_msg = f"Experimental konnte nicht geladen werden: {e}"
        g.menu_refresh()
        return task.done
    own = Game
    try:
        _pb_strip(g, sticky_keys_restore)
        g.__class__ = mod.Game
        mod.Game.__init__(g)
        os.environ["POLYBASH_EXP_SPEC"] = json.dumps(spec)
        mod._exp_autostart(g)
        _pb_rehook(g, "Polybash Experimental")
    except Exception:
        import traceback
        try:
            with open(_log_path(), "a", encoding="utf-8") as f:
                f.write(time.strftime("%Y-%m-%d %H:%M:%S") + " (Experimental-Start)\n" + traceback.format_exc() + "\n")
        except OSError:
            pass
        _pb_strip(g, getattr(mod, "sticky_keys_restore", lambda: None))
        g.__class__ = own
        g._pb_msg = "Experimental konnte nicht gestartet werden (spiel_fehler.log)"
        own.__init__(g, adopt=True)
        _pb_rehook(g, "Polybash")
    return task.done


def _pb_to_main(task, g):
    mod = _EXP_MOD
    _pb_strip(g, mod.sticky_keys_restore)
    g.__class__ = Game
    Game.__init__(g, adopt=True)
    _pb_rehook(g, "Polybash")
    return task.done


def _pb_back(g):
    """Von Robins leave_game aufgerufen: im nächsten Frame zurück zum Hauptmenü."""
    g.taskMgr.add(lambda task: _pb_to_main(task, g), "pb-switch", sort=-100)


def set_fullscreen(g, on):
    """Vollbild (in der Auflösung des Bildschirms) oder Fenster (1280x720). True, wenn die Anfrage gestellt werden konnte."""
    try:
        props = WindowProperties()
        if on:
            w, h = int(g.pipe.getDisplayWidth()), int(g.pipe.getDisplayHeight())
            if w < 640 or h < 480:
                return False
            props.setFullscreen(True)
            props.setSize(w, h)
        else:
            props.setFullscreen(False)
            props.setSize(1280, 720)
        g.win.requestProperties(props)
        return True
    except Exception:
        return False


def is_fullscreen(g):
    try:
        return bool(g.win.getProperties().getFullscreen())
    except Exception:
        return True


def default_fullscreen(g):
    """Beim ersten Start des Prozesses: Vollbild, außer F11 hat es in den Einstellungen abgeschaltet."""
    if os.environ.get("POLYBASH_FS_DONE") or os.environ.get("SPIEL_OFFSCREEN"):
        return
    os.environ["POLYBASH_FS_DONE"] = "1"
    try:
        want = load_settings().get("fs", True) is not False
    except Exception:
        want = True
    if want:
        set_fullscreen(g, True)


class Game(ShowBase):
    def __init__(self, adopt=False):
        if not adopt:                         # adopt=True: Fenster/ShowBase existieren schon (Rückkehr aus Experimental)
            ShowBase.__init__(self)
            load_ui_fonts(self.loader)
            self._pb_base = _pb_snapshot(self)
            default_fullscreen(self)
        self.disableMouse()
        self.setBackgroundColor(*SKY)
        self.render.setAntialias(AntialiasAttrib.MAuto)      # MSAA (wenn die Grafikkarte es kann)
        st = load_settings()
        self.gfx = "standard"                    # überall Standardgrafik (alte Einstellung "hoch" wird ignoriert)
        vd = st.get("vd")
        self.view_pct = int(vd) if isinstance(vd, (int, float)) and not isinstance(vd, bool) and 25 <= vd <= 300 else 100   # Sichtweite in %
        self.fog, self.fog_dens, self.far_base = None, 0.012, 450.0
        sv = st.get("sens")
        self.sens_mult = float(sv) if isinstance(sv, (int, float)) and not isinstance(sv, bool) and 0.5 <= sv <= 2.0 else 1.0
        fv = st.get("fov")
        self.fov_base = float(fv) if isinstance(fv, (int, float)) and not isinstance(fv, bool) and 60 <= fv <= 110 else FOV   # Sichtfeld
        self.invert_y = bool(st.get("inv"))      # Maus hoch/runter invertiert
        vm = st.get("vm")
        self.vol_music = int(vm) if isinstance(vm, (int, float)) and not isinstance(vm, bool) and 0 <= vm <= 100 else 100      # Hintergrundmusik in %
        vs_ = st.get("vs")
        self.vol_sfx = int(vs_) if isinstance(vs_, (int, float)) and not isinstance(vs_, bool) and 0 <= vs_ <= 100 else 100        # Soundeffekte in %
        self.fps_limit = st.get("fps") if st.get("fps") in FPS_CHOICES else 144
        lk = st.get("look")
        self.look_code = lk if look_valid(lk) else look_default(random.randrange(100000))     # Aussehen des Charakters
        self.apply_fps()
        self.overlay_kind = self.overlay_yes = None
        self.amb_np = None
        self.sky_root = self.sky_clouds = self.sun_np = self.filters = None
        self.vignette = self.land_np = None
        self.water_nps = []
        self.town_np = None                    # Stadt-Details (Bloecke, Wind, Fahnen)
        self.wind_nodes, self.flag_nodes, self.spin_nodes = [], [], []
        self.shadows = {}
        self.camLens.setFov(self.fov_base)
        self.camLens.setNearFar(0.1, 450)      # grosse Karten: siehe build_world (Fernsicht)
        self.fov_cur = self.fov_base
        self.prng = random.Random()

        # Spielzustand: erst das Startmenü, Welt und HUD entstehen in start_game()
        self.mode = "menu"          # menu | play
        self.net_mode = "single"    # single | host | client
        self.my_id = 0
        self.my_name = str(st.get("name") or (socket.gethostname() or "Spieler"))[:16]
        self.world = None
        self.player = None
        self.host = None            # HostSession (nur beim Host)
        self.client = None          # ClientSession (nur beim Mitspieler)
        self.listener = None        # Host-Suche im Menü
        self.attempt = None         # laufender Verbindungsversuch
        self.menu_items = []
        self.menu_lines = []                  # anklickbare Menüzeilen (Hot)
        self.card_hover = None                # Waffenkarte unter der Maus (Menü)
        self.menu_last = None
        self.menu_state = "name"
        self.menu_msg = ""
        self.ip_text = ""
        self.ip_edited = False
        self.lost_text = None
        self.cfg = dict(mode="koth", limit=10, mobs=MOB_DEFAULT, tomahawk=True, cd=int(STRIKE_CD), regen=REGEN_RATE,
                        resp=RESPAWN_DEFAULT, map=None)   # Host-Einstellungen
        self.name_back = "main"               # wohin "Weiter" im Namensmenü führt
        self.map_list = []                    # gefundene Kartendateien (Name, Pfad)
        self.dead_since = None                # Zeitpunkt des eigenen Todes (Anzeige der Wartezeit)
        self.menu_cards = []                  # Kacheln hinter den Menüknöpfen (Hot, Knoten)
